--[[
    ПЬЯНЫЙ ПЕТУХ — FUST Survival 0.59 DELTA+XENO (красно-чёрная)
    Скрипт сделан на основе скрипта VOMAGLA (подход к трассерам
    пуль и ESP взят оттуда, спасибо автору VOMAGLA).

    НОВОЕ В 0.49 — ОТКАТ НА СТАБИЛЬНУЮ БАЗУ, ОСТАВЛЕНА ТОЛЬКО АВТО-СТРЕЛЬБА:
    • База — СТАБИЛЬНАЯ 0.39 (та, что работала ДО партии изменений,
      после которой начались зависания игры). Все остальные «новые
      функции» той партии УДАЛЕНЫ: есп лута (новый), чамсы шкафов,
      обход анти-чита (лог чата/баннеров) — их в этой сборке НЕТ.
    • ФРИКАМ ВЫРЕЗАН И НА DELTA, И НА XENO — и секция в меню, и весь
      движок (он заякоривал персонажа и забирал левый джойстик).
    • ОСТАВЛЕНА ТОЛЬКО АВТО-СТРЕЛЬБА (0.39v2-v4) с ПРОВЕРКОЙ СТЕН:
      WallCheck — не тратит патроны на цели за стеной; телефон-фикс:
      выбор ветки по TouchEnabled (не по лживому KeyboardEnabled),
      стрельба Tool:Activate() на телефоне, mouse1click/VirtualInput-
      Manager на ПК, фолбэк — Tool:Activate().
    • b64-иконка заменена на rbxassetid: b64-декодер с битовыми
      операторами НЕ парсится компилятором Delta — именно из-за него
      0.48 умирала при компиляции (строка 4744, "got '6'").
    • Всё остальное — как в стабильной 0.39: ESP игроков/НПС, мешки/
      лут (слоты/владелец/чамсы как было), аимбот+злой аим, анти-отдача,
      трассеры, хитбоксы, HUD, CS2-прицел, вайтлист, конфиги, кнопка-петух.

    НОВОЕ В 0.58 — X-RAY ЛОВИТ СТЕНЫ (E-23):
    • Жалоба: «иксрей делает только двери прозрачными, а стены нет».
      Причина: матч был РЕГИСТРОЗАВИСИМЫЙ и по узкому набору ключей —
      если игра зовёт стены «wall»/«TWIG» строчными или прячет части
      глубже 2 моделей, стены не ловились (двери с «Door» ловились).
    • 0.58: матч БЕЗ УЧЁТА РЕГИСТРА (имя и ключ в lower); +ключи
      Block/Ceil/Pillar/Beam/Slab/Glass и русские Стен/Двер/Крыш/
      Фундамент/Забор/Окн/Перекрыт/Лестниц/Постройк/Блок; поиск по
      именам родителей углублён с 2 до 4 уровней.
    • Если стены всё равно не ловятся: Логи -> Журнал чита пишет
      «X-RAY: примеры имён стен/объектов» — скинь эту строку, добавлю
      точные ключи. Прямо сейчас на любой версии работает режим
      «X-Ray: ВСЁ вокруг (дикий)» — прозрачит все статичные части.
    • Всё из 0.57 внутри (фрикам E-22, кнопка в Конфигах, стрельба,
      FOV-круг).

    НОВОЕ В 0.59 — МУЛЬТИ-ТОЧКИ ФРИКАМА: СОХРАНЯЙ СКОЛЬКО УГОДНО МЕСТ:
    • Жалоба: во фрикаме хранилась только ОДНА точка — каждое нажатие
      SAVE POS перезаписывало её. 0.59: SAVE POS ДОБАВЛЯЕТ НОВУЮ точку
      в список (до 20) — можно сохранить все нужные места и летать
      между ними.
    • ПАНЕЛЬ CAM: новая строка «< POS 3 (2/5) >» — стрелки листают
      сохранённые точки по кругу; TP CAM TO POS летит в ВЫБРАННУЮ
      точку; DEL POS удаляет выбранную (первый тап — «SURE?», второй
      удаляет — случайное удаление невозможно).
    • ТОЧКИ НЕ ПРОПАДАЮТ после перезахода: список живёт в файле
      FUST_freecam_pos.json в воркспейсе экзекутора (Delta и Xeno дают
      writefile; файла нет — просто начнёшь список заново).
    • «Запоминать позицию камеры» работает с выбранной точкой: при
      выключении фрикама она обновляется, при включении камера
      стартует из неё.
    • Всё из 0.58 внутри (X-Ray ловит стены E-23, фрикам на Xeno E-22,
      «ВЫКЛЮЧИТЬ СКРИПТ» в Конфигах, стрельба, FOV-круг).

    НОВОЕ В 0.57 — ФРИКАМ НА XENO ПОЧИНЕН (E-22) + «ВЫКЛЮЧИТЬ СКРИПТ» В КОНФИГАХ:
    • ФРИКАМ НА ПК/XENO НЕ ЛЕТАЛ И НЕ КРУТИЛСЯ: клавиши шли ТОЛЬКО через
      ContextActionService (на Xeno они не доходили), вверх/вниз были
      только на E/Q, обзор — только ПКМ+мышь. 0.57: РЕЗЕРВНЫЙ ОПРОС
      IsKeyDown каждый кадр (полёт работает всегда; без хуков — только
      чтение клавиш, безопасно), SPACE = вверх, LEFT CTRL = вниз (E/Q
      остались), ОБЗОР НА СТРЕЛКАХ + ПКМ+мышь + свободный обзор при
      захваченной мышью, CAS-бинд в pcall (упадёт — фрикам всё равно
      включится), СТРОКА ПОДСКАЗОК клавиш в меню фрикама.
    • Кнопка «ВЫКЛЮЧИТЬ СКРИПТ» перенесена со страницы Main в раздел
      «Конфиги» (по приказу пользователя).
    • Всё из 0.56 внутри (старая стрельба, безопасный фрикам, FOV-круг).

    НОВОЕ В 0.56 — СТАРАЯ СТРЕЛЬБА + ФРИКАМ БЕЗ КАСАНИЯ ПЕРСОНАЖА + FOV-КРУГ:
    • БАН «WALKSPEED 1000, IQ 0» (10 лет, был на 0.54): разобран. В 0.55
      уже удалён телепорт ПЕРСОНАЖА к камере (TELEPORT TO CAM). В 0.56
      удалена и ЯКОРЬ-ЗАМОРОЗКА: фрикам больше НЕ ПИШЕТ НИ ОДНОГО свойства
      персонажа (ни Anchored, ни CFrame, ни скоростей) — просто отключает
      управление, персонаж стоит как обычный игрок. Летает ТОЛЬКО камера.
    • АВТО-СТРЕЛЬБА: движок VOMAGLA (0.52) НЕ СТРЕЛЯЛ — вернули СТАРЫЙ
      движок (линия 0.39-0.51, тот, что работал на Xeno): ПК —
      mouse1click / VirtualInputManager, телефон — Tool:Activate().
    • FOV-КРУГ «КРУТОЙ» (по скрипту пользователя): GUI-кольцо с ВРАЩАЮЩИМСЯ
      градиентом — красно-чёрное, когда аимбот никого не видит, и сплошное
      ЗЕЛЁНОЕ, когда цель захвачена. Цвета обоих состояний, толщина линии и
      скорость вращения настраиваются. Работает даже без Drawing API.
    • Всё из 0.55 внутри (меню фрикама, логи, журнал, конфиги, X-Ray).

    НОВОЕ В 0.55 — ФРИКАМ-МЕНЮ + ЛОГИ/ЖУРНАЛ + КОНФИГИ С ПОДТВЕРЖДЕНИЕМ + X-RAY:
    • ПАНЕЛЬ CAM = МЕНЮ ФРИКАМА: тап по кнопке CAM на экране БОЛЬШЕ НЕ
      включает полёт — открывает меню. В меню: скрыть меню (крестик в
      правом верхнем углу), FLY (вкл/выкл полёта), скорость −/+,
      SAVE POS (сохранить позицию) и TP CAM TO POS (телепорт КАМЕРЫ в
      сохранённую точку). Кнопку «телепорт персонажа к камере» УДАЛИЛИ.
    • ЛОГИ ПОЧИНЕНЫ: текст больше не вылезает из поля вбок и вниз — поле
      стало многострочным, с переносом строк и рамкой по размеру секции.
    • ЖУРНАЛ ЧИТА на странице Логи (вкладка «Журнал»): всё, что чит пишет
      (включения, ошибки, диагностика X-Ray), теперь ВИДНО в меню — раньше
      журнал был только файлом на диске, на телефоне его не открыть.
    • НАСТРОЙКИ И MAIN ОБЪЕДИНЕНЫ В ОДНУ СТРАНИЦУ «Main»: Кнопка меню,
      Оформление (НАСТРОЙКА ЦВЕТОВ МЕНЮ вернулась!), Конфиги — подвкладки.
    • УЛУЧШЕННЫЕ КОНФИГИ: список конфигов (Petuh/Configs), Создать /
      Загрузить / Сохранить / Удалить / Обновить. ПЕРЕД перезаписью и
      удалением вылезает ПОДТВЕРЖДЕНИЕ — случайную перезапись не даст
      сделать. Конфиг хранит ВСЕ настройки меню.
    • X-RAY: теперь ловит постройки по имени парта И по имени модели-
      родителя (раньше матчили только имя парта — у построек FUST оно
      общее, потому X-Ray не работал НИ НА ЧЁМ). Ключи расширены:
      wood/plank/wall/roof/foundation/ramp/stairs/door/gate/stone/metal...
      Плюс НОВЫЙ РЕЖИМ «X-Ray: ВСЁ вокруг (дикий)» — прозрачными
      становятся все статичные объекты, просвет гарантирован.
    • Старый одиночный конфиг «Сохранить/Загрузить» (FUST_config.json)
      убран — вместо него улучшенные конфиги со списком.

    НОВОЕ В 0.54 — ПЕРЕНОСЫ МЕНЮ + X-RAY ФИКС + КНОПКА XRAY ВКЛ/ВЫКЛ:
    • «Экран» (Аимбот): в неё переехали АНТИ-ОТДАЧА и АНТИ-ТРЯСКА (были на
      главной подвкладке Аимбота).
    • «ПУЛИ» сдвинуты в ЛЕВУЮ колонку — настройки доставать удобнее.
    • ТИМ ЧЕК АИМА ВЫРЕЗАН: вайтлист и тим чек — одно и то же. Кто свой —
      выбирается тапом в вайтлисте. «Тим чек ESP» теперь называется
      «Не показывать тимейтов» и остался на месте.
    • ВАЙТЛИСТ переехал с Main на страницу «Визуалы».
    • «ВИЗУАЛЫ» — теперь ОТДЕЛЬНАЯ СТРАНИЦА чита (Фильтры / Мир и освещение /
      Вайтлист), а не подвкладка ESP.
    • «БОТЫ И НПС» переехали ВНУТРЬ ESP (подвкладка «Боты и НПС»).
    • X-RAY ДОРАБОТАН: прозрачность применяется прямо по ходу скана, ключ
      "Twig" ловит все twig-объекты, в журнал пишется сколько стен найдено
      (если 0 — примеры имён стен с карты: так увидим, что переименовала игра).
    • КНОПКА XRAY НА ЭКРАНЕ в формате ВКЛ/ВЫКЛ: надпись и цвет показывают
      состояние, тап переключает, тянется пальцем. Прозрачность — слайдер
      «X-Ray: прозрачность стен» на странице Визуалы.

    НОВОЕ В 0.53 — ВОЗВРАТ ВЫРЕЗАННОГО + ПРИЦЕЛ/ПУЛИ VOMAGLA + ПОДСКАЗКИ (i):
    • ВОЗВРАЩЕНЫ функции, вырезанные в 0.49: ЧАМСЫ МЕБЕЛИ (шкафы/ящики/
      локеры/стеллажи/комоды/кровати/двери — вкладка ESP -> Лут -> Мебель)
      и СТРАНИЦА «ЛОГИ» (лог киков/банов FUST_kicks.log: кнопки Обновить/
      Очистить + авто-обновление). ЛУТ-ESP и слоты/владелец уже были —
      починены (см. ниже). Фрикам и X-Ray оставлены НОВЫЕ (0.50-0.52),
      старые версии 0.45 не возвращал — новые лучше.
    • ПРИЦЕЛ И ЕГО НАСТРОЙКИ взяты ИЗ VOMAGLA 1-в-1: вращение, пульс,
      радуга, точка, следование за целью/точкой аима, длина/зазор/толщина.
      Старый CS2-прицел убран. Вкладка Аимбот -> «Прицел».
    • ПУЛИ (ТРЕЙСЕРЫ) ПЕРЕРАБОТАНЫ НА ДВИЖОК VOMAGLA: перехват РЕАЛЬНЫХ
      выстрелов (hookmetamethod __namecall -> Raycast, луч не дальше 5 м
      от камеры). Старый детектор «быстрая часть + прямая» СПАМИЛ пулями
      от бегущих игроков и тимейтов — УДАЛЁН. Настройки VOMAGLA 1-в-1:
      6 текстур, ширина, прозрачность, время жизни, цвет + ТИМ ЧЕК ПУЛЬ
      (ВКЛ по умолчанию). Вкладка Аимбот -> «Пули».
    • ПОДВКЛАДКИ АИМБОТА: «Экран» (FOV-круг), «Прицел», «Пули» — как в
      ESP подвкладки Лут/Визуалы. Тим чек аима переехал в ESP -> Визуалы.
    • ПОДСКАЗКИ «i»: у КАЖДОЙ функции кнопка-инфо в кружочке — что делает,
      как настроить ползунок, когда включать. Описания из скобок в названиях
      переехали в подсказки. ЗАЩИТА ОТ СЛУЧАЙНЫХ ТАПОВ (телефон): открывается
      только короткий чистый тап (сдвиг < 14px, удержание < 0.7с), свайп-
      скролл от кнопки подсказку НЕ открывает; пока подсказка открыта,
      первый тап по строке закрывает её и НЕ жмёт саму функцию.
    • БИНДЫ-КНОПКИ ДЛЯ ТЕЛЕФОНА: плавающая кнопка XRAY (ESP -> Визуалы)
      тогглит X-Ray тапом; кнопка CAM фрикама теперь живёт отдельно от
      панели — можно спрятать панель, а бинд оставить.
    • ФИКСЫ ЛУТА: постоянный обход Workspace каждые 3с УДАЛЁН (лагал даже
      на ПК — слоты/владелец сканировали всю карту); скан один раз при
      включении чанками, инфо читается только у мешков в радиусе, ESP лута
      20 раз/с вместо каждого кадра. ЧАМСЫ ЛУТА: если игра сносит Highlight,
      теперь детектится и включаются квадраты-заливки.
    • Внутри все фиксы 0.52: E-15/E-16/E-17 (движок выстрела VOMAGLA).

    НОВОЕ В 0.52 — АВТО-СТРЕЛЬБА НА ДВИЖКЕ VOMAGLA (E-17):
    • Движок выстрела взят ИЗ VOMAGLA (пользователь гонял VOMAGLA на
      телефоне — НЕ КРАШИЛСЯ НИ РАЗУ): mouse1click → VirtualInputManager
      (нажатие + отжатие через task.defer — клик живёт до конца кадра)
      → Tool:Activate() как финальный фолбэк телефона.
    • УБРАНО ветвление по UserInputService.KeyboardEnabled/TouchEnabled:
      экзекуторы на телефоне врут во флагах, VOMAGLA не ветвится вообще
      и работает на Delta. Один путь выстрела для всех устройств.
    • task.defer НЕ yield — aim loop не ломается (в отличие от task.wait).
    • Внутри все фиксы 0.51: E-15 (стартовый скан Workspace вешал Delta
      чёрным экраном — убит, скан X-Ray только по тумблеру, чанками) и
      E-16 (CanvasGroup → Frame). Остальной код байт-в-байт 0.51.

    НОВОЕ В 0.51 — ФИКС «ЧЁРНОГО ЭКРАНА» НА DELTA (E-15/E-16):
    • УБИТ СТАРТОВЫЙ СКАН WORKSPACE (регистрация twig-стен X-Ray,
      стр. 7367 в 0.50): task.spawn с полным GetDescendants() и БЕЗ
      единого yield блокировал планировщик Roblox целиком — рендер
      замирал за чёрным сплэшем, Android вешал/убивал приложение.
      Xeno (ПК) проходил скан за 1-2 сек и не замечал, Delta (телефон)
      умирал. Теперь скана при старте НЕТ: twig-объекты регистрируются
      через DescendantAdded, а полный скан запускается ТОЛЬКО при
      включении X-Ray — чанками по 2000 объектов с task.wait().
    • CanvasGroup в панели фрикама заменён на Frame (E-16): лишний
      рендер-таргет на слабых мобильных GPU. Анимация панели теперь
      через UIScale + Visible.
    • БОЛЬШЕ НИЧЕГО НЕ ТРОНУТО — остальной код байт-в-байт 0.50.

    НОВОЕ В 0.50 — БАГФИКСЫ + X-RAY + ФРИКАМ + КОПТЕРЫ + КРАСНО-ЧЁРНАЯ ТЕМА:
    • ИСПРАВЛЕН КРАШ НА СТАРТЕ (стр.5321 «missing method Colorpicker»):
      колорпикеры вызывались на СЕКЦИЯХ, у которых такого метода нет —
      пересажены на тогглы (5 мест + Settings-страница). Полный список
      найденных ошибок и их статус — в файле BUGS.md (на GitHub).
    • ИСПРАВЛЕН ЭКРАН ЗАГРУЗКИ: не убирался из-за битого вызова
      Instance.new с типом TweenInfo (это не Instance) внутри pcall.
      Теперь убирается всегда, в т.ч. при фатальной ошибке, и
      показывает актуальную версию.
    • X-RAY (из VOMAGLA): просвет twig-стен — вкл/выкл, прозрачность,
      кейбинд на ПК (Xeno) со сменой клавиши (тапни [X] и нажми новую).
    • ФРИКАМ ВЕРНУЛСЯ (universal_freecam_v13, open source): отдельная
      страница «Фрикам» в меню, плавающая панель CAM (скрывается),
      кейбинды вкл/выкл (P) и скорость +/− ([ и ]), телефон — джойстик,
      ПК — WASD/QE/Shift. Персонаж ставится на якорь; аимбот и
      анти-тряска на время фрикама отключаются. hookfunction-подмена
      IsKeyDown ВЫКЛЮЧЕНА по умолчанию (хук-методы детектит анти-чит).
    • КОПТЕРЫ — отдельная цель аимбота БЕЗ проверки дистанции:
      «Кого аимить» -> Коптеры. Лимит Aim.Distance на них не действует
      (из-за него аим и не брал летающие коптеры). FOV/стены — как у всех.
    • КРАСНО-ЧЁРНАЯ ТЕМА: меню, сплэш, кнопка-петух, HUD, панель фрикама.
    • ЧИСТКА КОДА: дубли инициализации, мёртвые заглушки фрикама,
      битый твин-код, кейбинд меню теперь реально меняет клавишу.

    НОВОЕ В 0.39 — FPS/ТЕКСТУРЫ + ФРИКАМ ФИКС + АДМИН-ЧЕК + CS2 ПРИЦЕЛ + ИКОНКА + ЭКРАН ЗАГРУЗКИ:
    • УХУДШЕНИЕ ТЕКСТУР ДЛЯ FPS: MaterialService.Use2022Materials=false,
      всем BasePart.Material=Plastic, MeshPart.TextureID="", отключение
      TrackMaterials/Decals. Слайдер «Ухудшение текстур» в Визуалы.
    • ФРИКАМ ФИКС «БЕЖИТ НА МЕСТЕ / ЛЕТИТ»: WalkSpeed=0, JumpPower=0,
      AutoRotate=false, Humanoid:ChangeState(Physics) — тело реально
      стоит, анимация бега не играется. Якорь HRP оставлен.
