    • Функция выключена — аимбот работает как раньше, полностью
      руками (тумблер или хоткей). Настройки сохраняются в конфиг.
    • БАН-БЕЗОПАСНОСТЬ: только чтение позиций игроков (как у ESP), в
      игру ничего не отправляется, никаких хуков.

    НОВОЕ В 0.31 — АНТИ-ОТДАЧА/ТРЯСКА ТОЛЬКО ПОСЛЕ ВЫСТРЕЛА + СВОЯ ГРУППА:
    • ФИКС «МЫШКУ УВОДИТ ВНИЗ»: слой компенсации дрифта (АО) раньше
      работал ВСЕГДА, пока в руках оружие. Любое плавное ведение прицела
      вверх он считал отдачей, запоминал «якорь» (прицел до подъёма) и
      каждый кадр тянул камеру обратно вниз. Теперь все слои анти-отдачи
      и анти-тряски действуют только в «окне выстрела»: 0.6с после
      нажатия огня, окно продлевается, пока виден характер отдачи.
      Вне стрельбы камера не трогается вообще.
    • ФИКС «ТРЯСЁТ ЭКРАН ПРИ ХОДЬБЕ»: те же слои воевали с покачиванием
      камеры игры. Сброс CameraOffset глушил покачивание каждый кадр,
      детектор «дрожи прицела» принимал качание головы при беге за
      дрожь от выстрела (флипы направления без выстрела больше НЕ
      включают якорь), слой крена тоже работал всегда. Всё это теперь
      только в окне выстрела.
    • Слой 1 «откат кика камеры» больше не воюет с аимботом: пока
      аимбот ведёт цель — откат спит. И считается только в окне
      выстрела + 0.5с на хвост.
    • UI: все тумблеры/ползунки анти-отдачи и анти-тряски переехали в
      отдельную группу «Анти-отдача и тряска» на вкладке Аимбот (правая
      колонка, под «Цель»). Флаги конфига не менялись — настройки
      сохранятся сами.

    НОВОЕ В 0.30 — ВКЛАДКА «ВИЗУАЛЫ» + ФИКСЫ ДЕЛЬТЫ/МЕЛКОГО:
    • НОВАЯ ВКЛАДКА «ВИЗУАЛЫ» на странице ESP. Раньше FullBright/NoFog
      висели секцией на вкладке ESP, а трассеры — среди ESP-тумблеров.
      Теперь всё красящее разложено по местам:
        – «Фильтры» — новый TEAM CHECK: не показывать тимейтов
          (бокс/имя/дистанция/предмет/хелсбар, чамсы и хитбоксы
          сокомандников не трогаются, пока тумблер включён);
        – «Мир и освещение» — FullBright, NoDecoration, No Grass, No Fog;
        – «Трассеры пуль» — переезжают сюда со вкладки ESP.
      Порядок вкладок страницы: ESP | Визуалы | Лут.
    • ФИКС КРАСНОГО СПАМА В КОНСОЛИ. На телефоне окно меню бывает больше
      экрана, и math.clamp(позиция, 0, отрицательное) в перетаскивании
      кидал «invalid argument #3 to 'clamp' (max must be greater than or
      equal to min)» на каждое касание (строки 625/650 старой сборки).
      Теперь если окно шире/выше экрана — по этой оси не зажимаем.
    • ФИКС АИМ-КРУГА И ПРИЦЕЛА: FOV-круг и красный прицел создаются
      через SafeDrawing. Если экзекутор падает на Drawing.new("Circle")
      или ("Line") — скрипт больше не умирает на этих строках, аимбот
      продолжает работать без оверлея, в консоль пишется причина.
      Мёртвые объекты больше не трогаются после выгрузки.
    • Конфиг: Team Check сохраняется и загружается вместе с остальным.

    НОВОЕ В 0.29 — ESP РЮКЗАКОВ С ЛУТОМ (добыча убитых игроков):
    • Рюкзак, который остаётся после смерти игрока, подсвечивается
      ТЁМНО-ЗЕЛЁНЫМ: рамка по габариту, чей лут, сколько слотов
      забито и дистанция. Новая вкладка «Лут» на странице ESP.
    • «ЧЕЙ ЛУТ» читаем из подписи самой игры: рюкзаки почти всегда
      подписаны (ProximityPrompt «Обыскать», атрибуты Owner/Player).
      Если в подписи есть ник игрока с сервера — показываем ник,
      иначе подпись целиком («Рюкзак Ванюши»). Только чтение.
    • «СКОЛЬКО СЛОТОВ ЗАБИТО»: читаем атрибуты рюкзака (UsedSlots/
      Slots/ItemCount…) и содержимое. Если игра отдаёт «занято/всего»
      — покажет «12/24»; если только число предметов — «N предм.»;
      если ничего не нашли — «слоты ??». Включи «Диагностику» во
      вкладке «Лут» и пришли лог — поправлю паттерны под игру.
    • Рюкзаки ищутся фоновым сканом раз в секунду + мгновенно через
      DescendantAdded; ищем по именам (Рюкзак/Backpack/Сумка/Труп…),
      по подписи-промпту и по тегам игры (FustBackpack и т.п.).
    • БАН-БЕЗОПАСНОСТЬ: как весь остальной ESP — только чтение мира
      (имена/атрибуты/подписи) и Drawing у себя на клиенте. В игру
      ничего не летит, никаких хуков и перехватов.

    НОВОЕ В 0.28 — АИМ ПО КАТЕГОРИЯМ + HUD + МАСШТАБ ESP + ПОЛЗУНКИ:
    • АИМ БОЛЬШЕ НЕ АГРИТСЯ НА СПЯЩИХ: цели аима теперь по категориям.
      Мультидропдаун «Кого аимить»: Игроки / Боты и НПС (охранники и
      мирные) / Животные / Слиперы. Животные и слиперы по умолчанию
      ВЫКЛ — включаются вручную, если понадобятся.
    • ХИТБОКСЫ НПС ТОЖЕ ПО КАТЕГОРИЯМ: на странице «Боты и НПС» два
      новых тумблера «Хитбокс: животные» и «Хитбокс: слиперы» (по
      умолчанию ВЫКЛ). Спящим телам больше не раздувает хитбоксы,
      пока сам не включишь. Охранники и мирные — как раньше.
    • ПОЛЗУНКИ ПОЧИНЕНЫ (было «местами банально не видно»): дорожка
      слайдера растягивалась UIFlexItem'ом в одной строке с названием
      и значением — в узких секциях flex схлопывался в 0px. Теперь
      слайдер двухстрочный: сверху название и значение, снизу дорожка
      во всю ширину секции. Схлопнуться больше нечему.
    • ВЕСЬ ESP РЕАГИРУЕТ НА ДИСТАНЦИЮ: чем дальше игрок/НПС, тем мельче
      его бокс, текст, хелсбар и обводка (в пределах читаемого с
      телефона минимума). Тумблер «Сжатие ESP по дистанции» в секции
      ESP возвращает старый фиксированный размер.
    • МИКРО-HUD НА ЭКРАНЕ: FPS, пинг, ТПС сервера, число игроков.
      Секция «HUD на экране» (страница ESP): вкл/выкл, размер текста,
      прозрачность фона и текста, угол экрана, показ ТПС и фона.
      Панелька перетаскивается пальцем, маленькая и полупрозрачная.
      ТПС считается ЛОКАЛЬНО по workspace:GetServerTimeNow() — это
      чтение синхронизированных часов, никаких запросов в игру,
      бан-риска нет (как у ESP). Если сервер лагает — ТПС это покажет.

    РАНЕЕ (0.27) — КАТЕГОРИИ НПС: ОХРАННИКИ / МИРНЫЕ / ЖИВОТНЫЕ /
    СЛИПЕРЫ (ESP больше не помечает всех подряд):
    • Раньше «ESP ботов» выделял ЛЮБОГО НПС. Теперь каждый НПС попадает
      ровно в ОДНУ категорию — ESP не пересекаются, у каждой свой цвет:
        – «Охранники (враждебные НПС)» — оранжевый; это НПС на РТ:
          имя «Охранник» ИЛИ оружие в руках;
        – «Мирные НПС» — зелёный; все остальные НПС из папки Npcs;
        – «Животные» — красный; медведь, волк, олень, кабан (папка
          Animals, теги FustAnimal/FustDino + имена моделей);
        – «Слиперы (спящие игроки)» — голубой; тела игроков, оставшиеся
          в мире после выхода: по меткам игры И по позе (лежит дольше
          4 секунд — спит).
    • По умолчанию включены только ОХРАННИКИ.
    • У каждой категории свой колорпикер, цвет меняется на лету.
    • Чамсы ботов красятся цветом категории (охранники — оранжевые,
      дистанция по-прежнему до потолка).
    • Распознавание по структуре самой игры (папки Npcs/Animals, теги
      FustNpc/FustAnimal/FustDino) + по именам моделей.
    • «Диагностика: лог НПС в консоль» — раз в 10 секунд печатает имя,
      папку, теги и категорию каждого НПС. Если кого-то определило не
      туда — пришли, что в логе, поправлю паттерны.
    • БАН-БЕЗОПАСНОСТЬ: как и раньше — только чтение мира и рисование
      на своём клиенте (Drawing/Highlight), в игру ничего не летит.

    РАНЕЕ (0.26) — БОТЫ/НПС + АВТО-ПРЕДИКТ + «КВАДРАТНЫЙ» ТРАССЕР:
    • Починен «баганый» ползунок прозрачности: после отмены касания
      (Delta часто сам снимает тач) слайдер продолжал ехать от ЛЮБОГО
      касания экрана. Теперь хвост драга закрывается всегда, а шаг
      округляется к ближайшему значению, а не вниз — упор в максимум
      больше не откатывается на шаг ниже (0.9 не превращается в 0.85).
    • Новый стиль трассера «Квадратный» (в дропдауне стиля): объёмная
      квадратная «труба» из 4 рёбер + яркое ядро по центру. Крупнее
      обычной полоски, чётко видна, настоящая 3D-форма — сечение
      перпендикулярно полёту пули. Толщина/прозрачность/затухание —
      те же слайдеры, вид меняется на лету.
    • Новая страница «Боты и НПС»:
        – ESP ботов: оранжевый бокс, ник модели, дистанция, хелсбар,
          предмет в руках — всё как у игроков, но оранжевым;
        – чамсы ботов оранжевым (AlwaysOnTop, дистанция — до потолка);
        – ХИТБОКСЫ НПС И БОТОВ — отдельная функция со своим размером
          и прозрачностью (хитбоксы игроков не трогает).
    • Аимбот теперь целится и в ботов/НПС: мультидропдаун «Кого аимить»
      (Игроки / Боты и НПС) на вкладке «Цель». Боты ищутся сами
      (модели с Humanoid вне списка игроков).
    • АВТО-ПРЕДИКТ: упреждение считается само под цель, которую взял
      аимбот — чем дальше цель, тем больше упреждение; у ботов и НПС
      скорость сглаживается, чтобы их рывки не дёргали прицел. Ручной
      слайдер «Предикт» при включённом авто-предикте не используется,
      есть коэффициент подстройки.
    • ESP игроков починен на дальней дистанции: дальше ~1200м бокс
      сжимался меньше пикселя и пропадал, а на границе радиуса мигал.
      Теперь бокс дотягивается до минимального читаемого размера и
      работает гистерезис — ESP стабилен до 3000м (лимит по умолчанию
      теперь 3000м).
    • Чамсы игроков: привязка к «Max Distance» снята — видны до потолка.
    • БАН-БЕЗОПАСНОСТЬ: ничего нового в игру не отправляется — ESP/
      чамсы/трассеры рисуются только у тебя на клиенте (Drawing/Beam/
      Highlight), хитбоксы НПС меняются тем же способом, что и хитбоксы
      игроков раньше. Никаких hookmetamethod, перехватов и хуков.

    РАНЕЕ (0.25) — ОКОННЫЙ РЕЖИМ + ФУЛЛСКРИН (починка телефона):
    • Починено «меню за рамками экрана»: окно зажимается в границы
      экрана (запуск, открытие, поворот, перетаскивание); по умолчанию
      — оконный вид под размер телефона.
    • Кнопка ФУЛЛСКРИНА в топбаре рядом с шестерёнкой: тап — растянуть,
      повторный тап — вернуть оконный вид. Иконка заливается.
    • Ресайз окна: минимум 320x240 (было 900x600).

    РАНЕЕ (0.24) — ХОТКЕЙ АИМБОТА (ПК):
    • К тумблеру «Аимбот (камера-лок)» прикреплена клавиша — по
      умолчанию RightAlt. ЛЕВЫЙ клик по кнопке клавиши — захват новой
      клавиши (Esc — отвязать), ПРАВЫЙ клик — режим Toggle / Hold /
      Always. Клавиша и режим сохраняются в конфиг. Хоткей не сраба-
      тывает, пока ввод занят текстом; на телефоне кнопка не создаётся.

    РАНЕЕ (0.23) — НОВАЯ БИБЛИОТЕКА + УНИВЕРСАЛЬНОСТЬ:
    • Меню переписано на встроенную библиотеку — Avilon больше НЕ
      грузится из интернета: запуск быстрее, не зависит от чужих
      репозиториев. Готов к запуску в Delta (Android) и Xeno (ПК).
    • Плавающая кнопка-петух: тап — открыть/скрыть меню, потянуть —
      переместить. Окно подгоняется под маленький экран.
    • «Аим парт» и «Приоритет» — дропдауны. Акцент меню — янтарный.
    • Всё прежнее работает: ESP, чамсы, хитбоксы, аимбот, анти-отдача,
      анти-тряска, трассеры пуль (стили луча), No Fog, FullBright.

    С НУМЕРАЦИЕЙ: версии 0.22, 0.23, 0.24, 0.25, 0.26, 0.27, 0.28, 0.29, 0.30, 0.31, 0.32, 0.33, 0.34, 0.35, 0.36,
    ...
    (прошлые обозначения V2–V21 сохранены в истории ниже).

    РАНЕЕ (V2–0.22):
    1. 0.22 — стиль луча трассеров: дропдаун с 6 текстурами VOMAGLA
       (Луч, Молния, Сердцебиение, Цепь, Глитч, Вихрь) — на лету.
    2. V21 — трассеры в стиле VOMAGLA (Beam-пул) + починен No Fog
       (гасим Atmosphere Density/Haze — FogEnd на него не действовал).
    3. V20 — детектор пуль «быстро + по прямой», один трассер на пулю.
    4. V19 — анти-тряска при выстреле (крен / позиция / дрожь прицела).
    5. V18 — No Fog, деактивация кнопкой, трекинг пуль.
    6. V17 — слой дрифта анти-отдачи: якорь + плавный возврат.
    7. V16 — слой 3 анти-отдачи (плавная отдача, Bad Business).
    8. V15 — ESP Предмет (что в руках).
    9. V14 — безопасная анти-отдача (без hookmetamethod) + журнал
       FUST_journal.txt для диагностики банов.
    10. V13 — прозрачность хитбокса и чамсов, чамсы хитбокса.
    11. V12 — отозвана (hookmetamethod — бан-риск).
    12. V11 — починены хитбоксы и чамсы (зомби-цикл, FUST_SESSION).
    13. V10 — хитбоксы отвязаны от «Max Distance»; возврат размеров.
    14. V9 — три подвкладки в Main; V8 — две колонки; V7 — вкладки.
    15. V6 — конфиги FUST_config.json.
    16. ESP Box — 8 углов 3D-габарита, глубина через Dot (баг Delta).
    17. FullBright / NoDecoration / NoGrass / NoFog с возвратом.
    18. Вайтлист — своя панель, TextBox с клавиатурой.
    19. Аимбот: камера-лок, Smooth, предикт, FOV-круг, стены/команда.
    20. GUI в CoreGui, лог запуска [FUST] 1/4...4/4.
]]
