-- sethiddenproperty: используется для NoGrass/Decoration — обычно безопасно
local shp = type(sethiddenproperty) == "function"
table.insert(loadScreenDetected, shp and "sethiddenproperty: OK (для NoGrass)" or "sethiddenproperty: недоступен")
-- RequestStreamAroundAsync: легитимный API, низкий риск
table.insert(loadScreenDetected, "RequestStreamAroundAsync: легитимный API")
-- root.Size изменение (хитбоксы): сервер видит через raycast hit detection
table.insert(loadScreenDetected, "Hitbox.Size: серверный raycast видит — используем clamp 2..8")
-- camera.CFrame = (evil aim): сервер видит через Mouse.Hit сравнение
table.insert(loadScreenDetected, "camera.CFrame: используем лерп (не мгновенно)")
end)
end
local function updateLoadScreen()
if not LoadScreenEnabled then return end
local now = os.clock()
local elapsed = now - loadScreenStart
if loadScreenPhaseIdx <= #loadScreenPhases then
local phase = loadScreenPhases[loadScreenPhaseIdx]
local phaseTime = phase[1] * 3.0 -- 3с максимум
if elapsed >= phaseTime then
setLoadProgress(phase[1], phase[2])
if loadScreenPhaseIdx == 3 then
-- в фазе 3 запускаем реальную проверку
runLoadScreenCheck()
if loadScreenText then
loadScreenText.Text = "Проверки: " .. table.concat(loadScreenDetected, "  ||  ")
end
end
loadScreenPhaseIdx = loadScreenPhaseIdx + 1
end
end
if elapsed >= 3.0 then
hideLoadScreen()
end
end
if LoadScreenEnabled then
showLoadScreen()
loadScreenConn = game:GetService("RunService").RenderStepped:Connect(updateLoadScreen)
end
