-- 0.53: ПОДСКАЗКИ «i» — у каждой функции кнопка-инфо в кружочке. Тап
-- раскрывает описание: что делает, как настроить ползунок, когда включать.
-- ЗАЩИТА ОТ СЛУЧАЙНЫХ СРАБАТЫВАНИЙ (телефон):
-- 1) открывается только короткий чистый тап: сдвиг < 14px и удержание
--    < 0.7с — свайп-скролл, начатый на кнопке, подсказку НЕ открывает;
-- 2) повторный тап гасится 0.25с (дребезг пальца);
-- 3) пока подсказка открыта, первый тап по строке закрывает её и НЕ
--    жмёт саму функцию (нельзя случайно выключить аимбот);
-- 4) открыта может быть только одна подсказка — новая закрывает старую.
Library.InfoOpen = nil
Library.CreateInfoUI = function(self, InfoText, BtnProps, PanelParent, OnOpenChanged)
if not InfoText or InfoText == "" then
return nil
end
local InfoBtn = Instances:Create("TextButton", BtnProps)
InfoBtn.Instance.Text = "i"
InfoBtn.Instance.FontFace = Library.Font
InfoBtn.Instance.TextSize = 11
InfoBtn.Instance.AutoButtonColor = false
InfoBtn.Instance.BackgroundColor3 = Library.Theme["Element"]
InfoBtn.Instance.TextColor3 = Library.Theme["Text"]
InfoBtn.Instance.BackgroundTransparency = 0.2
InfoBtn.Instance.TextTransparency = 0.3
InfoBtn:AddToTheme({BackgroundColor3 = 'Element', TextColor3 = 'Text'})
Instances:Create("UICorner", {Parent = InfoBtn.Instance, Name = "\0", CornerRadius = UDimNew(1, 0)})
Instances:Create("UIStroke", {Parent = InfoBtn.Instance, Name = "\0", Color = Library.Theme["Outline"], ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Transparency = 0.25}):AddToTheme({Color = 'Outline'})
local InfoPanel = Instances:Create("Frame", {
Parent = PanelParent,
Name = "\0",
BackgroundColor3 = Library.Theme["Element"],
BorderColor3 = FromRGB(0, 0, 0),
BorderSizePixel = 0,
Visible = false,
Size = UDim2New(1, -8, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y
})
InfoPanel:AddToTheme({BackgroundColor3 = 'Element'})
Instances:Create("UICorner", {Parent = InfoPanel.Instance, Name = "\0", CornerRadius = UDimNew(0, 6)})
Instances:Create("UIStroke", {Parent = InfoPanel.Instance, Name = "\0", Color = Library.Theme["Accent"], ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Transparency = 0.55}):AddToTheme({Color = 'Accent'})
Instances:Create("UIPadding", {Parent = InfoPanel.Instance, Name = "\0", PaddingTop = UDimNew(0, 7), PaddingBottom = UDimNew(0, 8), PaddingLeft = UDimNew(0, 9), PaddingRight = UDimNew(0, 9)})
Instances:Create("TextLabel", {
Parent = InfoPanel.Instance,
Name = "\0",
FontFace = Library.Font,
TextColor3 = Library.Theme["Text"],
Text = InfoText,
TextWrapped = true,
TextXAlignment = Enum.TextXAlignment.Left,
TextYAlignment = Enum.TextYAlignment.Top,
TextTransparency = 0.12,
TextSize = 12,
BackgroundTransparency = 1,
BorderSizePixel = 0,
Size = UDim2New(1, 0, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y
}):AddToTheme({TextColor3 = 'Text'})
local open = false
local lastTapAt = 0
local function setOpen(v)
open = v
InfoPanel.Instance.Visible = v
InfoBtn.Instance.TextColor3 = v and Library.Theme.Accent or Library.Theme["Text"]
if v then
if Library.InfoOpen and Library.InfoOpen ~= InfoPanel and Library.InfoOpen._setOpen then
pcall(Library.InfoOpen._setOpen, false)
end
Library.InfoOpen = InfoPanel
elseif Library.InfoOpen == InfoPanel then
Library.InfoOpen = nil
end
if OnOpenChanged then
pcall(OnOpenChanged, v)
end
end
InfoPanel._setOpen = setOpen
InfoBtn._panelSetOpen = setOpen
local pressPos, pressAt = nil, nil
InfoBtn:Connect("InputBegan", function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
pressPos = input.Position
pressAt = os.clock()
end
end)
InfoBtn:Connect("InputEnded", function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
if pressPos and pressAt then
local moved = 0
pcall(function()
moved = (input.Position - pressPos).Magnitude
end)
local held = os.clock() - pressAt
if moved <= 14 and held <= 0.7 and os.clock() - lastTapAt > 0.25 then
lastTapAt = os.clock()
setOpen(not open)
end
end
pressPos = nil
pressAt = nil
end
end)
return InfoBtn
end
