AnchorPoint = Vector2New(0, 0.5),
PlaceholderColor3 = FromRGB(133, 139, 143),
PlaceholderText = Textbox.Placeholder,
TextSize = 16,
Size = UDim2New(0, 0, 0, 15),
TextColor3 = Library.Theme["Text"],
BorderColor3 = FromRGB(0, 0, 0),
Text = "",
Selectable = false,
BackgroundTransparency = 1,
Position = UDim2New(0, 0, 0.5, 0),
CursorPosition = -1,
BorderSizePixel = 0,
AutomaticSize = Enum.AutomaticSize.X
}):AddToTheme({TextColor3 = 'Text'})
end
-- 0.55: режим MultiLine — высокое поле с переносом строк (Логи/Журнал).
-- Без него текст вылезал из поля вбок под вкладки и вниз («логи не
-- читабельны»): у Input был AutomaticSize X и не было TextWrapped.
if Textbox.MultiLine then
Items["Textbox"].Instance.Size = UDim2New(1, 0, 0, 160)
Items["Textbox"].Instance.ClipsDescendants = true
Items["Text"].Instance.AnchorPoint = Vector2New(0, 0)
Items["Text"].Instance.Position = UDim2New(0, 0, 0, 0)
Items["Text"].Instance.Size = UDim2New(1, 0, 0, 15)
Items["Background"].Instance.AnchorPoint = Vector2New(0, 0)
Items["Background"].Instance.Position = UDim2New(0, 0, 0, 18)
Items["Background"].Instance.AutomaticSize = Enum.AutomaticSize.None
Items["Background"].Instance.Size = UDim2New(1, 0, 0, 138)
Items["Input"].Instance.AnchorPoint = Vector2New(0, 0)
Items["Input"].Instance.Position = UDim2New(0, 0, 0, 3)
Items["Input"].Instance.AutomaticSize = Enum.AutomaticSize.None
Items["Input"].Instance.Size = UDim2New(1, -4, 1, -8)
Items["Input"].Instance.TextWrapped = true
Items["Input"].Instance.MultiLine = true
Items["Input"].Instance.ClearTextOnFocus = false
Items["Input"].Instance.TextYAlignment = Enum.TextYAlignment.Top
Items["Input"].Instance.TextSize = 13
end
function Textbox:Get()
return Textbox.Value
end
function Textbox:SetVisibility(Bool)
Items["Textbox"].Instance.Visible = Bool
end
function Textbox:Set(Value)
if Textbox.Numeric then
if (not tonumber(Value)) and StringLen(tostring(Value)) > 0 then
Value = Textbox.Value
end
end
Textbox.Value = Value
Items["Input"].Instance.Text = Value
Library.Flags[Textbox.Flag] = Value
if Textbox.Callback then
Library:SafeCall(Textbox.Callback, Value)
end
end
if Textbox.Finished then
Items["Input"]:Connect("FocusLost", function(PressedEnterQuestionMark)
if PressedEnterQuestionMark then
Textbox:Set(Items["Input"].Instance.Text)
end
end)
else
Library:Connect(Items["Input"].Instance:GetPropertyChangedSignal("Text"), function()
Textbox:Set(Items["Input"].Instance.Text)
end)
end
if Textbox.Default then
Textbox:Set(Textbox.Default)
end
Library.SetFlags[Textbox.Flag] = function(Value)
Textbox:Set(Value)
end
return Textbox
end
end
-- 0.55: подтверждение опасных действий (перезапись/удаление конфига).
-- Простая модалка: Frame + 2 кнопки, БЕЗ CanvasGroup (урок E-16) и без
-- библиотечных зависимостей — работает и на Delta, и на Xeno.
local FUST_confirmGui = nil
function Library:FustConfirm(titleText, bodyText, yesText, onYes)
pcall(function()
if FUST_confirmGui then
FUST_confirmGui:Destroy()
FUST_confirmGui = nil
end
local confirmParent = (gethui and gethui()) or game:GetService("CoreGui")
local g = Instance.new("ScreenGui")
g.Name = "FUST_Confirm"
g.ResetOnSpawn = false
g.DisplayOrder = 999998
local okPar = pcall(function()
g.Parent = confirmParent
end)
if not okPar or not g.Parent then
g.Parent = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui") or game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 3)
end
if not g.Parent then return end
FUST_confirmGui = g
local card = Instance.new("Frame")
card.Size = UDim2.new(0, 330, 0, 182)
card.AnchorPoint = Vector2.new(0.5, 0.5)
card.Position = UDim2.new(0.5, 0, 0.5, 0)
card.BackgroundColor3 = Color3.fromRGB(24, 12, 12)
card.BorderSizePixel = 0
card.Active = true
card.Parent = g
local ccorner = Instance.new("UICorner")
ccorner.CornerRadius = UDim.new(0, 10)
ccorner.Parent = card
local cstroke = Instance.new("UIStroke")
cstroke.Thickness = 1.4
cstroke.Color = Color3.fromRGB(255, 45, 45)
cstroke.Transparency = 0.3
cstroke.Parent = card
local tt = Instance.new("TextLabel")
tt.Size = UDim2.new(1, -20, 0, 26)
tt.Position = UDim2.new(0, 10, 0, 8)
tt.BackgroundTransparency = 1
tt.Font = Enum.Font.GothamBold
tt.TextSize = 15
tt.TextColor3 = Color3.fromRGB(255, 90, 90)
tt.Text = titleText or "Подтверждение"
tt.TextXAlignment = Enum.TextXAlignment.Left
tt.Parent = card
local bb = Instance.new("TextLabel")
bb.Size = UDim2.new(1, -20, 1, -110)
bb.Position = UDim2.new(0, 10, 0, 36)
bb.BackgroundTransparency = 1
bb.Font = Enum.Font.Gotham
bb.TextSize = 13
bb.TextColor3 = Color3.fromRGB(235, 225, 225)
bb.TextWrapped = true
bb.TextYAlignment = Enum.TextYAlignment.Top
bb.TextXAlignment = Enum.TextXAlignment.Left
bb.Text = bodyText or ""
bb.Parent = card
local yes = Instance.new("TextButton")
yes.Size = UDim2.new(0.5, -14, 0, 34)
yes.Position = UDim2.new(0, 10, 1, -44)
yes.BackgroundColor3 = Color3.fromRGB(150, 25, 25)
yes.Font = Enum.Font.GothamBold
yes.TextSize = 13
yes.TextColor3 = Color3.fromRGB(255, 255, 255)
yes.Text = yesText or "ДА"
yes.AutoButtonColor = false
yes.Parent = card
local ycorner = Instance.new("UICorner")
ycorner.CornerRadius = UDim.new(0, 8)
ycorner.Parent = yes
local no = Instance.new("TextButton")
no.Size = UDim2.new(0.5, -14, 0, 34)
no.Position = UDim2.new(0.5, 4, 1, -44)
no.BackgroundColor3 = Color3.fromRGB(50, 30, 30)
no.Font = Enum.Font.GothamBold
no.TextSize = 13
no.TextColor3 = Color3.fromRGB(230, 220, 220)
no.Text = "ОТМЕНА"
no.AutoButtonColor = false
no.Parent = card
local ncorner = Instance.new("UICorner")
ncorner.CornerRadius = UDim.new(0, 8)
ncorner.Parent = no
local function fustConfirmClose()
if FUST_confirmGui then
FUST_confirmGui:Destroy()
FUST_confirmGui = nil
end
end
yes.MouseButton1Click:Connect(function()
fustConfirmClose()
if onYes then
pcall(onYes)
end
end)
no.MouseButton1Click:Connect(function()
fustConfirmClose()
end)
end)
end
Library.CreateSettingsPage = function(self, Window, Watermark, TargetPage)
-- 0.55: TargetPage = СУЩЕСТВУЮЩАЯ страница. Настройки сливаются с Main:
-- отдельная страница «Settings» больше не создаётся, все её секции
-- (Кнопка меню / Оформление / Конфиги) ложатся в переданную страницу.
local SettingsPage = TargetPage or Window:Page({Name = "Settings", Icon = "rbxassetid://80758916183665"})
do
-- 0.39: секция управления кнопкой/хоткеем меню
local MenuSection = SettingsPage:Section({Name = "Кнопка меню", Tab = "Меню", Icon = "rbxassetid://73803440257131"})
if MenuSection and MenuSection.Toggle then
local MenuHideBtnToggle = MenuSection:Toggle({
Name = "Скрыть кнопку-петух",
Flag = "PetuhBtnHidden",
Info = "Прячет круглую кнопку-петуха с экрана. Меню тогда открывается только хоткеем (по умолчанию RightControl, меняется рядом). Включай, если кнопка мешает стрелять или палится.",
Default = false,
Callback = function(state)
petuhSetBtnHidden(state)
end
})
-- 0.50 FIX: у СЕКЦИЙ нет метода Keybind (только Toggle/Label) — старый
-- MenuSection:Keybind ронял Settings-страницу в pcall: пропадали кейбинд
-- меню и тумблер «Экран загрузки». Теперь кейбинд на тоггле.
if MenuHideBtnToggle and MenuHideBtnToggle.Keybind then
UIRegistry.PetuhMenuKeyObj = MenuHideBtnToggle:Keybind({
Flag = "PetuhMenuKey",
Default = Enum.KeyCode.RightControl,
Mode = "Toggle",
Callback = function(state)
-- 0.50 FIX: библиотека шлёт ТОЛЬКО state (старый код ждал key —
-- клавишу сменить было нельзя). Ключ читаем из объекта кейбинда
-- и синхронизируем PETUH_MENU_KEY для хендлера ввода.
local kb = UIRegistry.PetuhMenuKeyObj
if kb and type(kb.Key) == "string" and kb.Key ~= "" then
local kname = kb.Key:gsub("Enum.KeyCode.", "")
if kname ~= "" and kname ~= "Backspace" and kname ~= "None" then
local okE, kc = pcall(function() return Enum.KeyCode[kname] end)
if okE and kc then
PETUH_MENU_KEY = kc
journal("КЛАВИША МЕНЮ: " .. kname)
end
end
end
end
})
end
MenuSection:Toggle({
Name = "Экран загрузки при старте",
Flag = "LoadScreenEnabled",
Info = "Красный сплэш с петухом при запуске (~3 сек): за это время скрипт проверяет экзекутор и риски функций. Отключи для быстрого входа — при следующем запуске сплэша не будет.",
Default = true,
Callback = function(state)
LoadScreenEnabled = state
-- 0.39: persist — пишем маркерный файл чтобы при следующем запуске скрипт знал
pcall(function()
if type(writefile) == "function" then
if state then
if type(delfile) == "function" then pcall(delfile, "FUST_noLoadScreen.txt") end
else
writefile("FUST_noLoadScreen.txt", "1")
end
end
end)
journal("ЭКРАН ЗАГРУЗКИ " .. (state and "ВКЛ" or "ВЫКЛ (не будет при следующем запуске)"))
end
})
MenuSection:Label("Кнопку можно перетащить в любое место. Скрытие — только ПК.")
end
local ThemingSection = SettingsPage:Section({Name = "Theming", Tab = "Оформление", Icon = "rbxassetid://73803440257131"})
do
for Index, Value in Library.Theme do
ThemingSection:Label(Index):Colorpicker({
Flag = Index.."_ThemingThing",
Default = Value,
Alpha = 0,
Callback = function(Value)
Library.Theme[Index] = Value
Library:ChangeTheme(Index, Value)
end
})
end
end
local ConfigsSection = SettingsPage:Section({Name = "Конфиги", Tab = "Конфиги", Icon = "rbxassetid://74885853379841"}) do
-- 0.55: УЛУЧШЕННЫЕ КОНФИГИ. Конфиг = файл в Petuh/Configs, хранит ВСЕ
-- настройки меню (тумблеры, ползунки, клавиши, цвета — через Flags).
-- Список в дропдауне; перед перезаписью и удалением — подтверждение.
local ConfigName
local ConfigSelected
local ConfigsDropdown = ConfigsSection:Dropdown({
Name = "Список конфигов",
Flag = "Configs",
Info = "Все сохранённые конфиги (папка Petuh/Configs). Выбери имя в списке и жми «Загрузить выбранный». Сохранение в существующий и удаление — только через подтверждение.",
Items = { },
Multi = false,
MaxSize = 120,
Callback = function(Value)
ConfigSelected = Value
end
})
ConfigsSection:Textbox({
Name = "Имя нового конфига",
Placeholder = "например: base-delta",
Flag = "ConfigName",
Callback = function(Value)
ConfigName = Value
end
})
local function cfgSafeName(n)
n = tostring(n or "")
n = n:gsub('[/\\%:%*%?"<>|%c]', "_")
n = n:gsub("^%s+", ""):gsub("%s+$", "")
return n
end
ConfigsSection:Button({
Name = "Создать новый",
Callback = function()
pcall(function()
local nm = cfgSafeName(ConfigName)
if nm == "" then return end
local path = Library.Folders.Configs .. "/" .. nm .. ".json"
if isfile(path) then
Library:FustConfirm("Конфиг уже существует", "Конфиг «" .. nm .. "» уже есть. Перезаписать его ТЕКУЩИМИ настройками? То, что было в нём сохранено, пропадёт.", "ПЕРЕЗАПИСАТЬ", function()
writefile(path, Library:GetConfig())
Library:RefreshConfigsList(ConfigsDropdown)
end)
else
writefile(path, Library:GetConfig())
Library:RefreshConfigsList(ConfigsDropdown)
end
end)
end
})
ConfigsSection:Button({
Name = "Загрузить выбранный",
Callback = function()
pcall(function()
if ConfigSelected and ConfigSelected ~= "" then
local path = Library.Folders.Configs .. "/" .. ConfigSelected .. ".json"
if isfile(path) then
Library:LoadConfig(readfile(path))
else
Library:RefreshConfigsList(ConfigsDropdown)
end
end
end)
end
})
ConfigsSection:Button({
Name = "Сохранить в выбранный",
Callback = function()
pcall(function()
if ConfigSelected and ConfigSelected ~= "" then
local path = Library.Folders.Configs .. "/" .. ConfigSelected .. ".json"
Library:FustConfirm("Перезапись конфига", "Записать ТЕКУЩИЕ настройки в конфиг «" .. ConfigSelected .. "»? То, что было сохранено в нём раньше, пропадёт.", "ПЕРЕЗАПИСАТЬ", function()
writefile(path, Library:GetConfig())
Library:RefreshConfigsList(ConfigsDropdown)
end)
end
end)
end
})
ConfigsSection:Button({
Name = "Удалить выбранный",
Callback = function()
pcall(function()
if ConfigSelected and ConfigSelected ~= "" then
local path = Library.Folders.Configs .. "/" .. ConfigSelected .. ".json"
Library:FustConfirm("Удаление конфига", "Удалить конфиг «" .. ConfigSelected .. "» навсегда? Восстановить его будет нельзя.", "УДАЛИТЬ", function()
delfile(path)
Library:RefreshConfigsList(ConfigsDropdown)
end)
end
end)
end
})
ConfigsSection:Button({
Name = "Обновить список",
Callback = function()
pcall(function()
Library:RefreshConfigsList(ConfigsDropdown)
end)
end
})
-- 0.57: «ВЫКЛЮЧИТЬ СКРИПТ» перенесена сюда со страницы Main (приказ).
ConfigsSection:Button({
Name = "ВЫКЛЮЧИТЬ СКРИПТ",
Callback = function()
pcall(function()
getgenv().FUST_Deactivate()
end)
end
})
Library:RefreshConfigsList(ConfigsDropdown)
end
end
return SettingsPage
end
end
Library.LucideIconsUrl = "https://raw.githubusercontent.com/Footagesus/Icons/refs/heads/main/lucide/dist/Icons.lua"
Library.IconPacks = Library.IconPacks or {}
Library.ActiveIconPack = "lucide"
function Library:LoadIconPack(Url, PackName)
PackName = PackName or "lucide"
if self.IconPacks[PackName] then
return self.IconPacks[PackName]
end
local Success, Result = pcall(function()
local Source = game:HttpGet(Url)
local Chunk = loadstring(Source)
if not Chunk then
return {}
end
local Icons = Chunk()
if type(Icons) ~= "table" then
return {}
end
return Icons
end)
self.IconPacks[PackName] = Success and Result or {}
return self.IconPacks[PackName]
end
function Library:SetIconPack(PackName)
self.ActiveIconPack = PackName or "lucide"
end
function Library:GetIconPack(PackName)
PackName = PackName or self.ActiveIconPack or "lucide"
if not self.IconPacks[PackName] then
if PackName == "lucide" then
self:LoadIconPack(self.LucideIconsUrl, "lucide")
else
self.IconPacks[PackName] = {}
end
end
return self.IconPacks[PackName] or {}
end
function Library:ResolveIcon(Icon, PackName)
if not Icon or Icon == "" then
return Icon
end
if typeof(Icon) ~= "string" then
return Icon
end
if Icon:match("^rbxassetid://") or Icon:match("^https?://") then
return Icon
end
local Icons = self:GetIconPack(PackName)
return Icons[string.lower(Icon)] or Icon
end
OriginalWindowFunction = Library.Window
Library.Window = function(self, Data)
Data = Data or {}
Data.Logo = self:ResolveIcon(Data.Logo)
Data.logo = self:ResolveIcon(Data.logo)
if Data.WatermarkLogo then
Data.WatermarkLogo = self:ResolveIcon(Data.WatermarkLogo)
end
return OriginalWindowFunction(self, Data)
end
OriginalSectionFunction = Library.Pages.Section
Library.Pages.Section = function(self, Data)
Data = Data or {}
Data.Icon = Library:ResolveIcon(Data.Icon or Data.icon)
Data.icon = Data.Icon
return OriginalSectionFunction(self, Data)
end
Library.CreateWindow = function(self, Data)
Data = Data or {}
local Window = self:Window(Data)
local Watermark
if Data.WatermarkEnabled then
Watermark = self:Watermark(
Data.WatermarkText or Data.Name or "Window",
self:ResolveIcon(Data.WatermarkLogo or Data.Logo)
)
Window.Watermark = Watermark
end
Window._AutoSettingsEnabled = Data.SettingsTabEnabled and true or false
Window._AutoSettingsWatermark = Watermark
local OriginalPage = Window.Page
local CreatingSettings = false
local function ReorderTabs()
local Order = 1
for _, Value in Window.Pages do
if Value ~= Window.SettingsPage and Value.Items and Value.Items["Inactive"] then
Value.Items["Inactive"].Instance.LayoutOrder = Order
Order = Order + 1
end
end
if Window.SettingsPage and Window.SettingsPage.Items and Window.SettingsPage.Items["Inactive"] then
Window.SettingsPage.Items["Inactive"].Instance.LayoutOrder = 999999
end
end
local function EnsureSettings()
if not Window._AutoSettingsEnabled or Window.SettingsPage or CreatingSettings then
ReorderTabs()
return
end
CreatingSettings = true
Window.SettingsPage = Library:CreateSettingsPage(Window, Window._AutoSettingsWatermark)
CreatingSettings = false
ReorderTabs()
end
local function WrappedPage(_, TabData)
TabData = TabData or {}
TabData.Icon = Library:ResolveIcon(TabData.Icon or TabData.icon)
TabData.icon = TabData.Icon
local Page = OriginalPage(Window, TabData)
EnsureSettings()
ReorderTabs()
return Page
end
Window.Page = WrappedPage
Window.CreateTab = WrappedPage
Window.CreatePage = WrappedPage
return Window
end
Library.CreateTab = Library.Page
Library.Pages.CreateSection = Library.Pages.Section
Library.Sections.CreateButton = Library.Sections.Button
Library.Sections.CreateToggle = Library.Sections.Toggle
Library.Sections.CreateSlider = Library.Sections.Slider
Library.Sections.CreateDropdown = Library.Sections.Dropdown
Library.Sections.CreateTextbox = Library.Sections.Textbox
Library.Sections.CreateLabel = Library.Sections.Label
function NormalizeNamedData(NameOrData, Icon)
if type(NameOrData) == "table" then
local Data = table.clone(NameOrData)
if Data.Title and not (Data.Name or Data.name) then
Data.Name = Data.Title
end
if Data.title and not (Data.Name or Data.name) then
Data.Name = Data.title
end
if Icon and not (Data.Icon or Data.icon) then
Data.Icon = Icon
end
return Data
end
local Data = {
Name = NameOrData
}
if Icon ~= nil then
Data.Icon = Icon
end
return Data
end
function Library:AddTab(NameOrData, Icon)
local Data = NormalizeNamedData(NameOrData, Icon)
Data.Icon = self:ResolveIcon(Data.Icon or Data.icon)
Data.icon = Data.Icon
if self.CreateTab then
return self:CreateTab(Data)
end
return self:Page(Data)
end
function Library.Pages:AddSection(NameOrData, Icon)
local Data = NormalizeNamedData(NameOrData, Icon)
Data.Icon = Library:ResolveIcon(Data.Icon or Data.icon)
Data.icon = Data.Icon
if self.CreateSection then
return self:CreateSection(Data)
end
return self:Section(Data)
end
function Library.Sections:AddButton(NameOrData, Callback)
if type(NameOrData) == "table" then
local Data = NormalizeNamedData(NameOrData)
return self:CreateButton(Data)
end
return self:CreateButton({
Name = NameOrData,
Callback = Callback
})
end
function Library.Sections:AddToggle(NameOrData, FlagOrCallback, Default, Callback)
if type(NameOrData) == "table" then
local Data = NormalizeNamedData(NameOrData)
return self:CreateToggle(Data)
end
local RealCallback = type(FlagOrCallback) == "function" and FlagOrCallback or Callback
return self:CreateToggle({
Name = NameOrData,
Flag = type(FlagOrCallback) == "string" and FlagOrCallback or nil,
Default = Default,
Callback = RealCallback
})
end
function Library.Sections:AddSlider(NameOrData, Min, Max, Default, Callback)
if type(NameOrData) == "table" then
local Data = NormalizeNamedData(NameOrData)
return self:CreateSlider(Data)
end
return self:CreateSlider({
Name = NameOrData,
Min = Min,
Max = Max,
Default = Default,
Callback = Callback
})
end
function Library.Sections:AddDropdown(NameOrData, Items, Default, Callback)
if type(NameOrData) == "table" then
local Data = NormalizeNamedData(NameOrData)
return self:CreateDropdown(Data)
end
return self:CreateDropdown({
Name = NameOrData,
Items = Items,
Default = Default,
Callback = Callback
})
end
function Library.Sections:AddTextbox(NameOrData, Placeholder, Callback)
if type(NameOrData) == "table" then
local Data = NormalizeNamedData(NameOrData)
return self:CreateTextbox(Data)
end
return self:CreateTextbox({
Name = NameOrData,
Placeholder = Placeholder,
Callback = Callback
})
end
function Library.Sections:AddLabel(TextOrData)
if type(TextOrData) == "table" then
local Data = NormalizeNamedData(TextOrData)
return self:CreateLabel(Data.Name or Data.Text or Data.text or "Label")
end
return self:CreateLabel(TextOrData)
end
getgenv().Library = Library
return Library
end)()
