return stroke
end
local function bindButtonBounce(btn, baseScale)
baseScale = baseScale or 1
local scale = Instance.new("UIScale")
scale.Scale = baseScale
scale.Parent = btn
btn.MouseButton1Down:Connect(function()
runSafeTween(btn, scale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
Scale = baseScale * 0.92,
})
end)
btn.MouseButton1Up:Connect(function()
runSafeTween(btn, scale, TweenInfo.new(0.12, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
Scale = baseScale,
})
end)
end
