-- 0.59: МУЛЬТИ-ТОЧКИ ФРИКАМА. Сохранённых точек теперь СПИСОК (до 20),
-- а не одна: SAVE POS добавляет новую, < / > листают, TP CAM TO POS летит
-- в выбранную, DEL POS удаляет (два тапа — защита от случайного удаления).
-- Список хранится в FUST_freecam_pos.json и переживает перезапуск.
local FC_HS = game:GetService("HttpService")
local FC_POS_FILE = "FUST_freecam_pos.json"
local FC_MAX_SLOTS = 20
local FC_Slots = {}
local FC_SlotIdx = 0
local FC_NextId = 1
local function fcSlotMirror()
if FC_SlotIdx >= 1 and FC_SlotIdx <= #FC_Slots then
local s = FC_Slots[FC_SlotIdx]
savedPos = Vector3.new(s.x, s.y, s.z)
savedPitch = s.pitch
savedYaw = s.yaw
else
savedPos = nil
savedPitch = nil
savedYaw = nil
end
end
local function fcSlotLabel()
local slotTxt = "ТОЧЕК: 0"
if #FC_Slots > 0 and FC_SlotIdx >= 1 and FC_SlotIdx <= #FC_Slots then
slotTxt = FC_Slots[FC_SlotIdx].name .. " (" .. FC_SlotIdx .. "/" .. #FC_Slots .. ")"
elseif #FC_Slots > 0 then
slotTxt = "ТОЧЕК: " .. #FC_Slots
end
pcall(function()
slotLbl.Text = slotTxt
end)
end
local function fcPersistPos()
pcall(function()
if type(writefile) ~= "function" then return end
local data = { sel = FC_SlotIdx, next = FC_NextId, slots = {} }
for i = 1, #FC_Slots do
local s = FC_Slots[i]
data.slots[i] = { name = s.name, x = s.x, y = s.y, z = s.z, pitch = s.pitch, yaw = s.yaw }
end
writefile(FC_POS_FILE, FC_HS:JSONEncode(data))
end)
end
local function fcLoadPosFile()
pcall(function()
if type(isfile) ~= "function" or not isfile(FC_POS_FILE) then return end
if type(readfile) ~= "function" then return end
local raw = readfile(FC_POS_FILE)
if type(raw) ~= "string" or #raw < 2 then return end
local okj, data = pcall(function()
return FC_HS:JSONDecode(raw)
end)
if not okj or type(data) ~= "table" or type(data.slots) ~= "table" then return end
for i = 1, #data.slots do
local s = data.slots[i]
if type(s) == "table" and type(s.x) == "number" and type(s.y) == "number" and type(s.z) == "number" and #FC_Slots < FC_MAX_SLOTS then
local nm = "POS " .. tostring(FC_NextId)
if type(s.name) == "string" and s.name ~= "" then nm = s.name end
FC_Slots[#FC_Slots + 1] = { name = nm, x = s.x, y = s.y, z = s.z, pitch = type(s.pitch) == "number" and s.pitch or 0, yaw = type(s.yaw) == "number" and s.yaw or 0 }
FC_NextId = FC_NextId + 1
end
end
if type(data.next) == "number" and data.next > FC_NextId then
FC_NextId = math.floor(data.next)
end
if type(data.sel) == "number" then
FC_SlotIdx = math.clamp(math.floor(data.sel), 0, #FC_Slots)
end
if #FC_Slots > 0 and (FC_SlotIdx < 1 or FC_SlotIdx > #FC_Slots) then
FC_SlotIdx = 1
end
end)
end
fcLoadPosFile()
fcSlotMirror()
fcSlotLabel()
if #FC_Slots > 0 then
journal("ФРИКАМ: загружено сохранённых точек: " .. #FC_Slots .. " (" .. FC_POS_FILE .. ")")
end
slotPrevBtn.MouseButton1Click:Connect(function()
if #FC_Slots == 0 then return end
FC_SlotIdx = FC_SlotIdx - 1
if FC_SlotIdx < 1 then FC_SlotIdx = #FC_Slots end
fcSlotMirror()
fcSlotLabel()
fcPersistPos()
end)
slotNextBtn.MouseButton1Click:Connect(function()
if #FC_Slots == 0 then return end
FC_SlotIdx = FC_SlotIdx + 1
if FC_SlotIdx > #FC_Slots then FC_SlotIdx = 1 end
fcSlotMirror()
fcSlotLabel()
fcPersistPos()
end)
local delArmed = false
delBtn.MouseButton1Click:Connect(function()
if FC_SlotIdx < 1 or FC_SlotIdx > #FC_Slots then
delBtn.Text = "NO POS!"
task.delay(0.9, function()
pcall(function()
delBtn.Text = "DEL POS"
end)
end)
journal("ФРИКАМ: удалять нечего — нет ни одной точки")
return
end
if not delArmed then
delArmed = true
delBtn.Text = "SURE?"
delBtn.TextColor3 = FC_RED
task.delay(2, function()
delArmed = false
pcall(function()
delBtn.Text = "DEL POS"
delBtn.TextColor3 = Color3.fromRGB(220, 210, 210)
end)
end)
return
end
delArmed = false
local nm = FC_Slots[FC_SlotIdx].name
table.remove(FC_Slots, FC_SlotIdx)
if #FC_Slots == 0 then
FC_SlotIdx = 0
elseif FC_SlotIdx > #FC_Slots then
FC_SlotIdx = #FC_Slots
end
fcSlotMirror()
fcSlotLabel()
fcPersistPos()
delBtn.Text = "DEL POS"
delBtn.TextColor3 = Color3.fromRGB(220, 210, 210)
journal("ФРИКАМ: точка " .. nm .. " удалена (осталось: " .. #FC_Slots .. ")")
end)
-- 0.55: панель CAM = МЕНЮ ФРИКАМА. Открывается тапом по кнопке CAM
-- (полёт НЕ трогает), скрытие — крестик в правом верхнем углу. Больше не
-- зависит от fcActive: меню можно открыть и до включения полёта.
local fcMenuOpen = false
local function fcMenuSet(open)
fcMenuOpen = open
if open then
hudFrame.Visible = true
hudScale.Scale = 0.8
runSafeTween("hud_pop", hudScale, TweenInfo.new(0.24, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
Scale = 1,
})
else
runSafeTween("hud_pop", hudScale, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
Scale = 0.85,
})
task.delay(0.14, function()
if not fcMenuOpen then
hudFrame.Visible = false
end
end)
end
end
-- 0.59: SAVE POS — добавить НОВУЮ точку в список (мульти-сохранение).
-- Работает и до включения фрикама (сохраняет, где сейчас смотрит камера).
saveBtn.MouseButton1Click:Connect(function()
local camera = Workspace.CurrentCamera
local np, npt, nyw
if fcActive then
np = camPos
npt = camPitch
nyw = camYaw
elseif camera then
local cf = camera.CFrame
np = cf.Position
local ox, oy, _ = cf:ToOrientation()
npt = math.deg(ox)
nyw = math.deg(oy)
end
if not np then return end
if #FC_Slots >= FC_MAX_SLOTS then
saveBtn.Text = "FULL!"
saveBtn.TextColor3 = FC_RED
task.delay(0.9, function()
pcall(function()
saveBtn.Text = "SAVE POS"
saveBtn.TextColor3 = Color3.fromRGB(220, 210, 210)
end)
end)
journal("ФРИКАМ: точек уже максимум (" .. FC_MAX_SLOTS .. ") — удали лишние кнопкой DEL POS")
return
end
local nm = "POS " .. tostring(FC_NextId)
FC_NextId = FC_NextId + 1
FC_Slots[#FC_Slots + 1] = { name = nm, x = np.X, y = np.Y, z = np.Z, pitch = npt, yaw = nyw }
FC_SlotIdx = #FC_Slots
fcSlotMirror()
fcSlotLabel()
fcPersistPos()
saveBtn.Text = "SAVED!"
saveBtn.TextColor3 = FC_RED
task.delay(0.9, function()
pcall(function()
saveBtn.Text = "SAVE POS"
saveBtn.TextColor3 = Color3.fromRGB(220, 210, 210)
end)
end)
journal("ФРИКАМ: точка " .. nm .. " сохранена (всего: " .. #FC_Slots .. "). < > — листать, TP — лететь")
end)
local function handleKeyAction(actionName, inputState, inputObject)
if not fcActive then
return Enum.ContextActionResult.Pass
end
-- 0.50: если открыт текстбокс (вайтлист и т.п.) — не глотаем клавиши
local focusedTextBox = nil
pcall(function()
focusedTextBox = UserInputService:GetFocusedTextBox()
end)
if focusedTextBox then
return Enum.ContextActionResult.Pass
end
if inputObject and inputObject.KeyCode then
local keyName = interceptedKeyCodes[inputObject.KeyCode]
if keyName then
local isDown = (inputState == Enum.UserInputState.Begin)
keysDown[keyName] = isDown
end
end
return Enum.ContextActionResult.Sink
end
inputBeganConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
if not fcActive then return end
if input.UserInputType == Enum.UserInputType.Touch and not gameProcessed then
local camera = Workspace.CurrentCamera
if not camera then return end
local vpSize = camera.ViewportSize
local touchPos = Vector2.new(input.Position.X, input.Position.Y)
if touchPos.X < (vpSize.X * 0.48) and not moveTouchId then
moveTouchId = input
joystickCenter = touchPos
joystickFrame.Position = UDim2.new(0, touchPos.X, 0, touchPos.Y)
joystickKnob.Position = UDim2.new(0.5, 0, 0.5, 0)
joystickVector = Vector2.zero
joystickFrame.Visible = true
elseif touchPos.X >= (vpSize.X * 0.48) and not lookTouchId then
lookTouchId = input
end
end
end)
inputChangedConnection = UserInputService.InputChanged:Connect(function(input, gameProcessed)
if not fcActive then return end
if input.UserInputType == Enum.UserInputType.Touch then
if input == moveTouchId then
local currentPos = Vector2.new(input.Position.X, input.Position.Y)
local delta = currentPos - joystickCenter
local dist = delta.Magnitude
if dist > joystickMaxRadius then
delta = delta.Unit * joystickMaxRadius
end
joystickKnob.Position = UDim2.new(0.5, delta.X, 0.5, delta.Y)
joystickVector = Vector2.new(delta.X / joystickMaxRadius, -delta.Y / joystickMaxRadius)
elseif input == lookTouchId then
local d = input.Delta
camYaw = camYaw - (d.X * FC_TouchSens)
camPitch = math.clamp(camPitch - (d.Y * FC_TouchSens), -89, 89)
end
end
if input.UserInputType == Enum.UserInputType.MouseMovement then
-- 0.57 (E-22): обзор мышью — ПКМ, ИЛИ когда мышь уже захвачена игрой
-- (MouseBehavior ~= Default). Оба чтения в pcall — на части экзекуторов
-- этих методов может не быть; стрелки остаются запасным каналом.
local rmbOk = false
pcall(function()
rmbOk = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
end)
local mouseLocked = false
pcall(function()
mouseLocked = UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default
end)
if rmbOk or mouseLocked then
local d = input.Delta
camYaw = camYaw - (d.X * FC_MouseSens)
camPitch = math.clamp(camPitch - (d.Y * FC_MouseSens), -89, 89)
end
end
end)
inputEndedConnection = UserInputService.InputEnded:Connect(function(input)
if input == moveTouchId then
moveTouchId = nil
joystickVector = Vector2.zero
joystickFrame.Visible = false
elseif input == lookTouchId then
lookTouchId = nil
end
end)
-- 0.57 (E-22): резервный опрос клавиш — полёт работает даже если
-- ContextActionService на экзекуторе не доставляет события (на Xeno из-за
-- этого не было движения). Только ЧТЕНИЕ состояния клавиш — без хуков,
-- анти-читу нечего детектить.
local function fcKey(name, enumKey)
if keysDown[name] then return true end
local okk, down = pcall(UserInputService.IsKeyDown, UserInputService, enumKey)
return okk and down or false
end
local function startFreecam()
local camera = Workspace.CurrentCamera
local char = LocalPlayer.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
local root = char and char:FindFirstChild("HumanoidRootPart")
if not camera or not char or not hum or not root then return end
hum:UnequipTools()
pcall(function()
FC_SGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false)
end)
-- 0.56: НИКАКИХ записей в персонажа (урок бана «WALKSPEED 1000», E-19)
if controls then
controls:Disable()
end
local touchGui = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("TouchGui")
if touchGui then
touchGui.Enabled = false
end
-- 0.57 (E-22): бинд в pcall — если CAS на экзекуторе падает, фрикам всё
-- равно включится (клавиши возьмёт резервный опрос fcKey).
pcall(function()
FC_CAS:BindActionAtPriority(
"FUSTFreecamKeySink",
handleKeyAction,
false,
SINK_PRIORITY,
Enum.KeyCode.W,
Enum.KeyCode.A,
Enum.KeyCode.S,
Enum.KeyCode.D,
Enum.KeyCode.E,
Enum.KeyCode.Q,
Enum.KeyCode.Space,
Enum.KeyCode.LeftControl,
Enum.KeyCode.Up,
Enum.KeyCode.Down,
Enum.KeyCode.Left,
Enum.KeyCode.Right,
Enum.KeyCode.LeftShift,
Enum.KeyCode.RightShift,
Enum.PlayerActions.CharacterForward,
Enum.PlayerActions.CharacterBackward,
Enum.PlayerActions.CharacterLeft,
Enum.PlayerActions.CharacterRight,
Enum.PlayerActions.CharacterJump
)
end)
if FreeCam.HookKeys then
fcInstallHook()
end
if FC_RememberPos and savedPos and savedPitch and savedYaw then
camPos = savedPos
camPitch = savedPitch
camYaw = savedYaw
else
local currentCF = camera.CFrame
camPos = currentCF.Position
local x, y, _ = currentCF:ToOrientation()
camPitch = math.deg(x)
camYaw = math.deg(y)
end
camera.CameraType = Enum.CameraType.Scriptable
renderConnection = RunService.RenderStepped:Connect(function(dt)
if getgenv().FUST_SESSION ~= FUST_SESSION then
pcall(function()
renderConnection:Disconnect()
end)
return
end
local camera = Workspace.CurrentCamera
if not camera then return end
-- 0.56: персонаж НЕ трогается каждый кадр (было: якорь + перезапись CFrame
-- + обнуление скоростей — именно такое состояние и ловит анти-чит, E-19)
local rotCFrame = CFrame.Angles(0, math.rad(camYaw), 0) * CFrame.Angles(math.rad(camPitch), 0, 0)
local moveVector = Vector3.zero
if joystickVector.Magnitude > 0.05 then
local right = rotCFrame.RightVector * joystickVector.X
local forward = rotCFrame.LookVector * joystickVector.Y
moveVector = moveVector + right + forward
end
-- 0.57 (E-22): СТРЕЛКИ = обзор камеры (работают всегда, через опрос).
if fcKey("Left", Enum.KeyCode.Left) then camYaw = camYaw + 140 * dt end
if fcKey("Right", Enum.KeyCode.Right) then camYaw = camYaw - 140 * dt end
if fcKey("Up", Enum.KeyCode.Up) then camPitch = math.clamp(camPitch + 90 * dt, -89, 89) end
if fcKey("Down", Enum.KeyCode.Down) then camPitch = math.clamp(camPitch - 90 * dt, -89, 89) end
local kbForward = 0
local kbRight = 0
local kbUp = 0
if fcKey("W", Enum.KeyCode.W) then kbForward = kbForward + 1 end
if fcKey("S", Enum.KeyCode.S) then kbForward = kbForward - 1 end
if fcKey("D", Enum.KeyCode.D) then kbRight = kbRight + 1 end
if fcKey("A", Enum.KeyCode.A) then kbRight = kbRight - 1 end
if fcKey("E", Enum.KeyCode.E) or fcKey("Space", Enum.KeyCode.Space) then kbUp = kbUp + 1 end
if fcKey("Q", Enum.KeyCode.Q) or fcKey("LCtrl", Enum.KeyCode.LeftControl) then kbUp = kbUp - 1 end
if kbForward ~= 0 or kbRight ~= 0 or kbUp ~= 0 then
local pcMove = (rotCFrame.LookVector * kbForward) + (rotCFrame.RightVector * kbRight) + (Vector3.new(0, 1, 0) * kbUp)
moveVector = moveVector + pcMove
end
if moveVector.Magnitude > 0 then
local currentMultiplier = (keysDown.LeftShift or fcKey("LeftShift", Enum.KeyCode.LeftShift) or fcKey("RightShift", Enum.KeyCode.RightShift)) and 2.0 or 1.0
camPos = camPos + (moveVector.Unit * (flySpeed * currentMultiplier * dt))
end
camera.CFrame = CFrame.new(camPos) * rotCFrame
end)
end
local function stopFreecam()
if renderConnection then
renderConnection:Disconnect()
renderConnection = nil
end
pcall(function()
FC_CAS:UnbindAction("FUSTFreecamKeySink")
end)
pcall(function()
FC_SGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
end)
moveTouchId = nil
lookTouchId = nil
joystickVector = Vector2.zero
joystickFrame.Visible = false
if controls then
controls:Enable()
end
local touchGui = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("TouchGui")
if touchGui then
touchGui.Enabled = true
end
for k in pairs(keysDown) do
keysDown[k] = false
end
if FC_RememberPos then
savedPos = camPos
savedPitch = camPitch
savedYaw = camYaw
-- 0.59: авто-запоминание при выключении обновляет ВЫБРАННУЮ точку списка
if FC_SlotIdx >= 1 and FC_SlotIdx <= #FC_Slots then
local s = FC_Slots[FC_SlotIdx]
s.x = camPos.X
s.y = camPos.Y
s.z = camPos.Z
s.pitch = camPitch
s.yaw = camYaw
fcPersistPos()
end
end
local camera = Workspace.CurrentCamera
local char = LocalPlayer.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
if camera and hum then
camera.CameraSubject = hum
end
-- 0.56: Anchored/скорости НЕ восстанавливаем — мы их не трогали (E-19)
if camera then
camera.CameraType = Enum.CameraType.Custom
end
end
local function fcSetEnabledInner(state)
if state == fcActive then return end
if state then
startFreecam()
if renderConnection then
-- старт удался
fcActive = true
FreeCam.Enabled = true
toggleBtn.Text = "CAM: ON"
flyBtn.Text = "FLY: ON" -- 0.55: синхронизация кнопки FLY в меню
runSafeTween("btn_col", toggleBtn, TweenInfo.new(0.12, Enum.EasingStyle.Quad), { TextColor3 = FC_RED })
runSafeTween("btn_strk", toggleStroke, TweenInfo.new(0.12, Enum.EasingStyle.Quad), { Color = FC_RED })
fcMenuSet(true)
journal("ФРИКАМ ВКЛ (скорость " .. tostring(flySpeed) .. ")")
else
-- нет персонажа/камеры — не включаемся, тоггл вернётся в ВЫКЛ
journal("ФРИКАМ: не смог включиться (нет персонажа?)")
end
else
fcActive = false
FreeCam.Enabled = false
stopFreecam()
toggleBtn.Text = "CAM: OFF"
flyBtn.Text = "FLY: OFF" -- 0.55: синхронизация кнопки FLY в меню
runSafeTween("btn_col", toggleBtn, TweenInfo.new(0.12, Enum.EasingStyle.Quad), { TextColor3 = Color3.fromRGB(245, 235, 235) })
runSafeTween("btn_strk", toggleStroke, TweenInfo.new(0.12, Enum.EasingStyle.Quad), { Color = Color3.fromRGB(255, 255, 255) })
fcMenuSet(false)
journal("ФРИКАМ ВЫКЛ")
end
pcall(function()
if UIRegistry.FCToggle and UIRegistry.FCToggle.Set then
UIRegistry.FCToggle:Set(fcActive)
end
end)
end
-- 0.55: тап по CAM открывает/скрывает МЕНЮ фрикама (полёт НЕ переключает —
-- полёт теперь кнопкой FLY внутри меню)
toggleBtn.MouseButton1Click:Connect(function()
fcMenuSet(not fcMenuOpen)
end)
flyBtn.MouseButton1Click:Connect(function()
fcSetEnabledInner(not fcActive)
end)
closeBtn.MouseButton1Click:Connect(function()
fcMenuSet(false)
end)
-- 0.59: TP CAM TO POS — телепорт КАМЕРЫ в ВЫБРАННУЮ точку списка (< >).
-- Если фрикам ещё не включён — включаем и переносим камеру в точку
-- (персонаж остаётся на месте).
tpCamBtn.MouseButton1Click:Connect(function()
if FC_SlotIdx < 1 or FC_SlotIdx > #FC_Slots then
journal("ФРИКАМ: нет сохранённых точек — нажми SAVE POS (можно несколько)")
tpCamBtn.Text = "NO POS!"
task.delay(0.9, function()
pcall(function()
tpCamBtn.Text = "TP CAM TO POS"
end)
end)
return
end
if not fcActive then
fcSetEnabledInner(true)
end
if fcActive then
local s = FC_Slots[FC_SlotIdx]
camPos = Vector3.new(s.x, s.y, s.z)
camPitch = s.pitch
camYaw = s.yaw
fcSlotMirror()
journal("ФРИКАМ: камера в точке " .. s.name .. " (" .. FC_SlotIdx .. "/" .. #FC_Slots .. ")")
end
end)
function fcSetEnabled(state)
fcSetEnabledInner(state and true or false)
end
function fcSpeedStep(dir)
flySpeed = math.clamp(flySpeed + dir * speedStep, minSpeed, maxSpeed)
FreeCam.Speed = flySpeed
pcall(function()
speedLabel.Text = "SPD: " .. tostring(flySpeed)
end)
end
function fcSetSpeed(v)
flySpeed = math.clamp(math.floor(v), minSpeed, maxSpeed)
FreeCam.Speed = flySpeed
pcall(function()
speedLabel.Text = "SPD: " .. tostring(flySpeed)
end)
end
function fcSetPanelVisible(v)
-- 0.53: кнопка CAM — бинд фрикама на телефоне — теперь живёт отдельно:
