FreeCam.PanelVisible = v and true or false
pcall(function()
toggleBtn.Visible = FreeCam.PanelVisible
end)
end
freecamEnable = function()
fcSetEnabled(true)
end
freecamDisable = function()
fcSetEnabled(false)
end
