-- 0.54: тап по кнопке = ТОТ ЖЕ путь, что тумблер в меню; если меню ещё
-- не собрано — переключаем напрямую (фолбэк)
function xrayQuickToggle()
if UIRegistry.XRayToggle and UIRegistry.XRayToggle.Set then
UIRegistry.XRayToggle:Set(not XRay.Enabled)
return
end
XRay.Enabled = not XRay.Enabled
if XRay.Enabled then
xrayScanAll(function()
if XRay.Enabled then
pcall(setXrayState, true, XRay.Transparency)
end
end)
else
pcall(setXrayState, false, XRay.Transparency)
end
journal("X-RAY " .. (XRay.Enabled and "ВКЛ" or "ВЫКЛ") .. " (кнопка на экране)")
xrayQuickSync()
end
