-- 0.53: КНОПКА XRAY НА ЭКРАНЕ — бинд для телефона (Delta): плавающая
-- кнопка, тап включает/выключает X-Ray, можно перетащить пальцем
-- (Draggable на телефоне не работает — свой drag через InputBegan/Changed).
xrayQuickGui = nil
xrayQuickBuild = function(state)
if state then
if xrayQuickGui and xrayQuickGui.Parent then
return
end
local okG, guiOrErr = pcall(function()
local g = Instance.new("ScreenGui")
g.Name = "FUST_XRayQuick"
g.ResetOnSpawn = false
local parent = LocalPlayer:FindFirstChildOfClass("PlayerGui")
if not parent then
parent = game:GetService("CoreGui")
end
g.Parent = parent
local btn = Instance.new("TextButton")
btn.Name = "XRayBtn"
btn.Size = UDim2.new(0, 92, 0, 34)
btn.Position = UDim2.new(1, -110, 0.34, 0)
btn.Text = "XRAY"
btn.Font = Enum.Font.GothamBold
btn.TextSize = 14
btn.TextColor3 = Color3.fromRGB(255, 70, 70)
btn.BackgroundColor3 = Color3.fromRGB(16, 10, 10)
btn.BackgroundTransparency = 0.25
btn.AutoButtonColor = false
btn.Active = true
btn.BorderSizePixel = 0
btn.Parent = g
local corner = Instance.new("UICorner")
corner.CornerRadius = UDim.new(1, 0)
corner.Parent = btn
local stroke = Instance.new("UIStroke")
stroke.Color = Color3.fromRGB(255, 45, 45)
stroke.Thickness = 1.4
stroke.Transparency = 0.35
stroke.Parent = btn
xrayQuickSync() -- 0.54: надпись ВКЛ/ВЫКЛ по текущему состоянию
local dragging = false
local dragStart, startPos = nil, nil
btn.InputBegan:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
dragging = true
dragStart = input.Position
startPos = btn.Position
input.Changed:Connect(function()
if input.UserInputState == Enum.UserInputState.End then
dragging = false
end
end)
end
end)
UserInputService.InputChanged:Connect(function(input)
if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
local delta = input.Position - dragStart
btn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
end
end)
btn.MouseButton1Click:Connect(function()
xrayQuickToggle()
end)
return g
end)
if okG then
xrayQuickGui = guiOrErr
else
warn("[FUST] Кнопка XRAY не создалась: " .. tostring(guiOrErr))
end
else
if xrayQuickGui then
pcall(function() xrayQuickGui:Destroy() end)
xrayQuickGui = nil
end
end
end
