pcall(function() xrayQuickBuild(state) end)
journal("КНОПКА XRAY " .. (state and "ВКЛ" or "ВЫКЛ"))
end
})

function normalizeName(raw)
if type(raw) ~= "string" then
return ""
end
local name = raw:gsub("^%s+", ""):gsub("%s+$", "")
name = name:gsub("^@", "")
return name
end
function resolveName(raw)
local name = normalizeName(raw)
if name == "" then
return nil
end
local lower = string.lower(name)
for _, plr in ipairs(Players:GetPlayers()) do
if string.lower(plr.Name) == lower then
return plr.Name
end
end
for _, plr in ipairs(Players:GetPlayers()) do
if string.lower(plr.DisplayName) == lower then
return plr.Name
end
end
return name
end
