wlButtonRow.Name = "FustWhitelistButtons"
wlButtonRow.BackgroundTransparency = 1
wlButtonRow.Size = UDim2.new(1, 0, 0, 32)
wlButtonRow.LayoutOrder = 6
wlButtonRow.Parent = wlPanel
do
local layout = Instance.new("UIListLayout")
layout.FillDirection = Enum.FillDirection.Horizontal
layout.Padding = UDim.new(0, 6)
layout.SortOrder = Enum.SortOrder.LayoutOrder
layout.Parent = wlButtonRow
end
function wlMakeButton(text, order, bg, fg)
local b = Instance.new("TextButton")
b.Font = Enum.Font.GothamBold
b.TextSize = 13
b.Text = text
b.TextColor3 = fg
b.BackgroundColor3 = bg
b.BorderSizePixel = 0
b.Size = UDim2.new(0.5, -3, 1, 0)
b.LayoutOrder = order
b.Parent = wlButtonRow
wlCorner(b, 5)
return b
end
wlAdd = wlMakeButton("+ Добавить", 1, WL_ACCENT, Color3.fromRGB(255, 255, 255))
wlRemove = wlMakeButton("- Убрать", 2, WL_ROW, WL_TEXT)
wlAdd.Activated:Connect(function()
local name = resolveName(wlInput.Text)
if name then
Whitelist[name] = true
rebuildPlayerList()
end
wlInput.Text = ""
pcall(function()
wlInput:ReleaseFocus()
end)
end)
wlRemove.Activated:Connect(function()
local name = resolveName(wlInput.Text)
if name then
Whitelist[name] = nil
rebuildPlayerList()
end
wlInput.Text = ""
pcall(function()
wlInput:ReleaseFocus()
end)
end)
Players.PlayerAdded:Connect(function()
task.defer(rebuildPlayerList)
end)
Players.PlayerRemoving:Connect(function()
task.defer(rebuildPlayerList)
end)
rebuildPlayerList()
