-- 0.56: FOV-КРУГ «КРУТОЙ» — GUI-версия по скрипту юзера (Frame + UICorner +
-- UIStroke + UIGradient, кольцо ВРАЩАЕТСЯ). Реакция на видимость: целей нет —
-- красно-чёрное кольцо (основной + затемнённый цвет), цель захвачена аимботом —
-- СПЛОШНОЙ зелёный. Работает даже в экзекуторах БЕЗ Drawing API. Создание
-- ленивое — ScreenGui появляется при первом показе, на старте ноль расхода.
fovGuiScreen = nil
fovGuiFrame = nil
fovGuiStroke = nil
fovGuiGradient = nil
fovGuiLastMain = nil
fovGuiLastTarget = nil
fovGuiEnsure = function()
if fovGuiScreen and fovGuiScreen.Parent then return true end
local okP, fParent = pcall(function()
return (gethui and gethui()) or game:GetService("CoreGui")
end)
if not okP or not fParent then
fParent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui")
end
pcall(function()
local old = fParent:FindFirstChild("FUSTFovCircle")
if old then old:Destroy() end
end)
local sg = Instance.new("ScreenGui")
sg.Name = "FUSTFovCircle"
sg.ResetOnSpawn = false
sg.IgnoreGuiInset = true
sg.DisplayOrder = 5
pcall(function()
sg.Parent = fParent
end)
if not sg.Parent then
sg.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui")
end
local fr = Instance.new("Frame")
fr.Name = "Circle"
fr.AnchorPoint = Vector2.new(0.5, 0.5)
fr.Position = UDim2.fromOffset(0, 0)
fr.Size = UDim2.fromOffset(Aim.FOV * 2, Aim.FOV * 2)
fr.BackgroundTransparency = 1
fr.Visible = false
fr.Parent = sg
local cr = Instance.new("UICorner")
cr.CornerRadius = UDim.new(1, 0)
cr.Parent = fr
local st = Instance.new("UIStroke")
st.Thickness = Aim.FovThickness
st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
st.Color = Aim.FovColorNoTarget
st.Parent = fr
local gr = Instance.new("UIGradient")
gr.Rotation = 0
gr.Parent = st
fovGuiScreen = sg
fovGuiFrame = fr
fovGuiStroke = st
fovGuiGradient = gr
fovGuiLastMain = nil
fovGuiLastTarget = nil
return sg.Parent ~= nil
end
fovGuiApplyColors = function(main, hasTarget)
if not fovGuiGradient then return end
fovGuiStroke.Color = main
if hasTarget then
-- цель захвачена — СПЛОШНОЙ цвет (по умолчанию зелёный)
fovGuiGradient.Color = ColorSequence.new(main)
else
-- целей нет — кольцо из основного + затемнённого (красно-чёрное)
local dark = Color3.new(main.R * 0.15, main.G * 0.15, main.B * 0.15)
fovGuiGradient.Color = ColorSequence.new{
ColorSequenceKeypoint.new(0.0, dark),
ColorSequenceKeypoint.new(0.5, main),
ColorSequenceKeypoint.new(1.0, dark),
}
end
end
fovGuiSetVisible = function(v)
if v then
if not fovGuiEnsure() then return end
fovGuiFrame.Visible = true
else
if fovGuiFrame then
fovGuiFrame.Visible = false
end
end
end
fovGuiUpdate = function(center, hasTarget)
if not Aim.ShowFOV then
fovGuiSetVisible(false)
return
end
if not fovGuiEnsure() then return end
fovGuiFrame.Position = UDim2.fromOffset(center.X, center.Y)
fovGuiFrame.Size = UDim2.fromOffset(Aim.FOV * 2, Aim.FOV * 2)
fovGuiStroke.Thickness = Aim.FovThickness
local main = hasTarget and Aim.FovColorTarget or Aim.FovColorNoTarget
if fovGuiLastTarget ~= hasTarget or fovGuiLastMain ~= main then
fovGuiApplyColors(main, hasTarget)
fovGuiLastTarget = hasTarget
fovGuiLastMain = main
end
fovGuiGradient.Rotation = (fovGuiGradient.Rotation + Aim.FovSpin) % 360
fovGuiFrame.Visible = true
end
fovGuiDestroy = function()
if fovGuiScreen then
pcall(function()
fovGuiScreen:Destroy()
end)
end
fovGuiScreen = nil
fovGuiFrame = nil
fovGuiStroke = nil
fovGuiGradient = nil
fovGuiLastMain = nil
fovGuiLastTarget = nil
end
-- 0.53: ДВИЖОК ПРИЦЕЛА ИЗ VOMAGLA (1-в-1): крест из 4 Drawing-линий,
-- вращение, пульс зазора, радуга, точка-квадрат, следование за целью
-- или за точкой аима (гладко, через exp-лерп). Старый CS2-прицел убран.
CH = {
Enabled = false,
Color = Color3.new(1, 1, 1),
Rainbow = false,
Length = 8,
Gap = 4,
Thickness = 1.5,
Dot = false,
RotationSpeed = 0,
Pulse = false,
PulseSpeed = 3,
FollowTarget = false,
FollowSmooth = 8,
FollowAimPoint = false,
}
chLines = {}
for i = 1, 4 do
local l = SafeDrawing("Line")
if l then
l.Visible = false
l.Thickness = CH.Thickness
l.Color = CH.Color
chLines[i] = l
end
end
chDot = SafeDrawing("Square")
if chDot then
chDot.Visible = false
chDot.Filled = true
chDot.Thickness = 1
chDot.Size = Vector2.new(2, 2)
chDot.Color = CH.Color
end
local chSmoothX, chSmoothY = nil, nil
local chElapsed = 0
local chRot = 0
AIM_TargetPart = nil
AIM_TargetScreenPos = nil
function updateCrosshairV(dt, center)
if not chLines[1] then
return
end
if not CH.Enabled then
for _, l in ipairs(chLines) do
l.Visible = false
end
if chDot then
chDot.Visible = false
end
return
end
local camera = Workspace.CurrentCamera
if not camera then
return
end
local vp = camera.ViewportSize
local cx, cy = center.X, center.Y
if CH.FollowAimPoint and AIM_TargetScreenPos then
cx, cy = AIM_TargetScreenPos.X, AIM_TargetScreenPos.Y
elseif CH.FollowTarget and AIM_TargetPart and AIM_TargetPart.Parent then
local okS, sp, vis = pcall(function()
local s, v = camera:WorldToViewportPoint(AIM_TargetPart.Position)
return s, v
end)
if okS and sp and vis then
cx, cy = sp.X, sp.Y
elseif okS and sp then
-- цель за спиной — прижимаем прицел к краю экрана (как в VOMAGLA)
local dx, dy = sp.X - cx, sp.Y - cy
local adx, ady = math.abs(dx), math.abs(dy)
local margin = 18
local sx = (vp.X * 0.5) - margin
local sy = (vp.Y * 0.5) - margin
local scale = 1
if adx > 0 or ady > 0 then
scale = math.min(sx / math.max(adx, 1e-6), sy / math.max(ady, 1e-6))
end
cx, cy = cx + dx * scale, cy + dy * scale
end
end
local smooth = math.clamp(CH.FollowSmooth, 1, 20)
local a = 1 - math.exp(-(dt or 0.016) * smooth)
if chSmoothX == nil then
chSmoothX, chSmoothY = cx, cy
end
chSmoothX = chSmoothX + (cx - chSmoothX) * a
chSmoothY = chSmoothY + (cy - chSmoothY) * a
chElapsed = chElapsed + (dt or 0.016)
chRot = (chRot + (dt or 0.016) * CH.RotationSpeed) % 360
local col = CH.Color
if CH.Rainbow then
col = Color3.fromHSV((chElapsed * 0.5) % 1, 1, 1)
end
local gap = CH.Gap
if CH.Pulse then
gap = gap + math.sin(chElapsed * CH.PulseSpeed) * math.max(CH.Gap * 0.4, 2)
end
local len = CH.Length
for i = 0, 3 do
local l = chLines[i + 1]
if l then
local ang = math.rad(chRot + i * 90)
local dx, dy = math.cos(ang), math.sin(ang)
l.Visible = true
l.Thickness = CH.Thickness
l.Color = col
l.From = Vector2.new(chSmoothX + dx * gap, chSmoothY + dy * gap)
l.To = Vector2.new(chSmoothX + dx * (gap + len), chSmoothY + dy * (gap + len))
end
end
if chDot then
chDot.Visible = CH.Dot
chDot.Color = col
chDot.Position = Vector2.new(chSmoothX - 1, chSmoothY - 1)
end
end
aimRayParams = RaycastParams.new()
aimRayParams.FilterType = Enum.RaycastFilterType.Exclude
aimRayParams.IgnoreWater = true
function resolveAimPart(character, choice)
local pick = choice
if pick == "Random" then
pick = AIM_PARTS[math.random(1, 3)]
end
if pick == "Head" then
return character:FindFirstChild("Head") or character:FindFirstChild("UpperTorso")
elseif pick == "Torso" then
return character:FindFirstChild("UpperTorso")
or character:FindFirstChild("Torso")
or character:FindFirstChild("HumanoidRootPart")
elseif pick == "Legs" then
return character:FindFirstChild("LeftLeg")
or character:FindFirstChild("RightLeg")
or character:FindFirstChild("LeftFoot")
or character:FindFirstChild("RightFoot")
end
return character:FindFirstChild("HumanoidRootPart")
end
function wallBetween(fromPos, targetChar, targetPos)
local filter = {}
if LocalPlayer.Character then
table.insert(filter, LocalPlayer.Character)
end
table.insert(filter, targetChar)
aimRayParams.FilterDescendantsInstances = filter
return Workspace:Raycast(fromPos, targetPos - fromPos, aimRayParams) ~= nil
end
evilVisCache = {}
evilVisCacheCount = 0
function evilBodyVisible(model, camPos)
-- КЭШ 0.15с: без него злой аим делал 2 raycast на каждого игрока КАЖДЫЙ кадр — это и есть лаги
local now = os.clock()
local hit = evilVisCache[model]
if hit and now - hit.at < 0.15 then
return hit.vis
end
if evilVisCacheCount > 40 then
table.clear(evilVisCache)
evilVisCacheCount = 0
end
local headP = model:FindFirstChild("Head") or model:FindFirstChild("UpperTorso")
local torsoP = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
local vis = false
if headP and not wallBetween(camPos, model, headP.Position) then
vis = true
end
if not vis and torsoP and not wallBetween(camPos, model, torsoP.Position) then
vis = true
end
evilVisCache[model] = { at = now, vis = vis }
evilVisCacheCount = evilVisCacheCount + 1
return vis
end
function evilAimPoint(model, root, camPos, dist)
if not evilBodyVisible(model, camPos) then
return nil, nil 
end
local center = root.Position
if not Evil.AutoPred then
return root, center
end
local okV, vel = pcall(function()
return root.AssemblyLinearVelocity
end)
if not okV or not vel then
return root, center
end
local hVel = Vector3.new(vel.X, 0, vel.Z)
if hVel.Magnitude < 1 then
return root, center 
end
local half = math.max(root.Size.X, root.Size.Z) * 0.5
local lead = math.clamp(dist / 900, 0.1, 1.5) * math.clamp(Evil.K or 1, 0.1, 5)
local dir = hVel.Unit
return root, center + dir * half + vel * lead
end
