function bpGetBBox(inst)
local e = trackedBackpacks[inst]
local now = os.clock()
if e and e.BBoxCF and e.BBoxSize and e.BBoxAt and now - e.BBoxAt < 0.5 then
return e.BBoxCF, e.BBoxSize
end
local cf, sz
if inst:IsA("Model") then
local okB, bcf, bsz = pcall(function()
return inst:GetBoundingBox()
end)
if okB and bcf and bsz then
cf, sz = bcf, bsz
end
elseif inst:IsA("BasePart") then
cf, sz = inst.CFrame, inst.Size
end
if not cf or not sz or sz.Magnitude <= 0 then
return nil
end
if sz.Magnitude > 60 then
sz = Vector3.new(2, 2, 2)
end
if e then
e.BBoxCF, e.BBoxSize, e.BBoxAt = cf, sz, now
end
return cf, sz
end
function bpProject(camera, cf, sz)
local camPos = camera.CFrame.Position
local look = camera.CFrame.LookVector
local hx = sz.X * 0.5 + 0.5
local hy = sz.Y * 0.5 + 0.5
local hz = sz.Z * 0.5 + 0.5
local minX, minY = math.huge, math.huge
local maxX, maxY = -math.huge, -math.huge
for i = 0, 7 do
local ox = (i % 2 == 0) and -hx or hx
local oy = (i % 4 < 2) and -hy or hy
local oz = (i < 4) and -hz or hz
local corner = (cf * CFrame.new(ox, oy, oz)).Position
if (corner - camPos):Dot(look) <= 0.1 then
return nil
end
local pt = camera:WorldToViewportPoint(corner)
if pt.X < minX then minX = pt.X end
if pt.X > maxX then maxX = pt.X end
if pt.Y < minY then minY = pt.Y end
if pt.Y > maxY then maxY = pt.Y end
end
return Vector2.new(minX, minY), Vector2.new(maxX - minX, maxY - minY)
end
function bpOwnerFromLabel(label)
if type(label) ~= "string" or #label < 5 then
return nil
end
local l = string.lower(label)
local pats = {
"^%s*(.-)'s%s*backpack%s*$", 
"^%s*(.-)s%s*backpack%s*$", 
"^%s*(.-)%s+backpack%s*$", 
"^%s*(.-)'s%s*loot%s*bag%s*$",
"^%s*(.-)s%s*loot%s*bag%s*$",
"^%s*(.-)%s+loot%s*bag%s*$",
"^рюкзак%s+(.+)%s*$", 
"^Рюкзак%s+(.+)%s*$", 
"^РЮКЗАК%s+(.+)%s*$", 
"^сумка%s+(.+)%s*$", 
"^Сумка%s+(.+)%s*$",
"^СУМКА%s+(.+)%s*$",
"^мешок%s+(.+)%s*$", 
"^Мешок%s+(.+)%s*$",
"^МЕШОК%s+(.+)%s*$",
"^труп%s+(.+)%s*$", 
"^Труп%s+(.+)%s*$",
"^ТРУП%s+(.+)%s*$",
}
for _, p in ipairs(pats) do
local _, _, cs, ce = string.find(l, p)
if cs and ce then
local owner = string.sub(label, cs, ce)
owner = owner:gsub("^[%s%p]+", ""):gsub("[%s%p]+$", "")
if #owner >= 2 then
return owner
end
end
end
return nil
end
bpOpenCacheInst = {} 
bpOpenCacheTitle = {} 
BP_OPEN_TTL = 1800 -- 0.39: было 900с (15мин). 30мин кэш безопаснее для FPS.
bpUiScanAt = {} 
function bpLooksLikeBagTitle(text)
if type(text) ~= "string" or #text < 4 or #text > 64 then
return false
end
return bpMatchesFragments(string.lower(text), {
"кзак", "КЗАК", "РЮКЗАК", "Рюкзак", "ackpack", "ACKPACK", "умк", "УМК",
"ешок", "ЕШОК", "руп", "РУП", "corpse", "CORPSE", "обыч", "ОБЫЧ",
"лут", "Лут", "ЛУТ", "loot", "Loot", "LOOT",
})
end
function bpSlotsFromUiText(text)
if type(text) ~= "string" or #text > 40 then
return nil
end
local t = string.lower(text)
if string.find(t, "счез", 1, true) or string.find(t, "ерез", 1, true)
or string.find(t, "xpire", 1, true) or string.find(t, "espawn", 1, true)
or string.find(t, "lapse", 1, true) or string.find(t, "кг", 1, true)
or string.find(t, "kg", 1, true) or string.find(t, "вес", 1, true)
or string.find(t, "weight", 1, true) or string.find(t, "минут", 1, true)
or string.find(t, "хп", 1, true) or string.find(t, "hp", 1, true) then
return nil
end
local u, m = string.match(text, "^%s*(%d+)%s*/%s*(%d+)%s*$")
if u and m then
return u .. "/" .. m
end
u, m = string.match(text, "(%d+)%s+из%s+(%d+)")
or string.match(text, "(%d+)%s+Из%s+(%d+)")
or string.match(text, "(%d+)%s+ИЗ%s+(%d+)")
if u and m then
return u .. "/" .. m
end
if #text <= 16 then
u, m = string.match(text, "(%d+)%s*/%s*(%d+)")
if u and m then
return u .. "/" .. m
end
end
return nil
end
function bpRememberOpenUI(owner, slots, titleLower)
if slots == nil and owner == nil then
return
end
local rec = { Owner = owner, Slots = slots, At = os.clock() }
if titleLower then
bpOpenCacheTitle[titleLower] = rec
end
local cam = Workspace.CurrentCamera
if cam then
local cc = cam.ViewportSize * 0.5
local best, bestD = nil, 320
for inst, e in pairs(trackedBackpacks) do
if (e.Cat or "bag") == "bag" then
local cf = e.BBoxCF
if not cf then
cf = bpGetBBox(inst)
end
if cf then
local okP, pt = pcall(function()
return cam:WorldToViewportPoint(cf.Position)
end)
if okP and pt and pt.Z > 0 then
local dd = (Vector2.new(pt.X, pt.Y) - cc).Magnitude
if dd < bestD then
best, bestD = inst, dd
end
end
end
end
end
if best then
bpOpenCacheInst[best] = rec
if S.Loot.DebugLog then
print("[FUST][ЛУТ-UI] запомнили мешок: владелец=" .. tostring(owner) .. " слоты=" .. tostring(slots))
end
end
end
end
function bpCaptureBagGui(gui, force)
local now = os.clock()
if not force and bpUiScanAt[gui] and now - bpUiScanAt[gui] < 8 then
return
end
bpUiScanAt[gui] = now
local okD, desc = pcall(function()
local out = {}
local stack = { gui }
while #stack > 0 and #out < 800 do
local node = table.remove(stack)
local kids = node:GetChildren()
for i = #kids, 1, -1 do
local k = kids[i]
table.insert(out, k)
if #out >= 800 then
break
end
table.insert(stack, k)
end
end
return out
end)
if not okD or type(desc) ~= "table" then
return
end
local titleIdx, title, titleLower, owner
for idx, d in ipairs(desc) do
if titleIdx then
break
end
if d:IsA("TextLabel") or d:IsA("TextButton") then
local okT, txt = pcall(function()
return tostring(d.Text)
end)
if okT and txt and bpLooksLikeBagTitle(txt) then
titleIdx, title, titleLower = idx, txt, string.lower(txt)
owner = bpOwnerFromLabel(txt)
if owner and (string.find(string.lower(owner), "ерсонаж", 1, true)
or string.find(string.lower(owner), "владел", 1, true)) then
owner = nil
end
end
end
end
if titleIdx == nil then
return
end
local slots, slotsWeak
local lastIdx = math.min(#desc, titleIdx + 400)
for idx = titleIdx + 1, lastIdx do
local d = desc[idx]
if d:IsA("TextLabel") or d:IsA("TextButton") then
local okT, txt = pcall(function()
return tostring(d.Text)
end)
if okT and txt then
local s = bpSlotsFromUiText(txt)
if s then
if string.match(txt, "^%s*(%d+)%s*/%s*(%d+)%s*$") then
slots = s
break
elseif slotsWeak == nil then
slotsWeak = s
end
end
end
end
end
slots = slots or slotsWeak
if S.Loot.DebugLog then
print("[FUST][ЛУТ-UI] экран мешка: заголовок=[" .. tostring(title)
.. "] владелец=" .. tostring(owner) .. " слоты=" .. tostring(slots))
end
bpRememberOpenUI(owner, slots, titleLower)
end
function bpScanOpenBagUI()
local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
