-- 0.50: старые заглушки фрикама удалены (чистка кода) — движок
-- вернулся и объявлен выше (universal_freecam_v13): freecamEnable и
-- freecamDisable теперь настоящие, FreeCam.Enabled синхронизируется.
LOOT_POOL_SIZE = 12
LOOT_POOL_INTERVAL = 1.2 -- 0.39: было 0.35 — лагало на ПК. 1.2с достаточно.
lootChamPool = {}
lootChamPoolAt = 0
lootChamPoolBlocked = false
lootChamPoolWanted = nil 
function lootPoolDisableAll()
for _, h in ipairs(lootChamPool) do
pcall(function()
h.Enabled = false
h.Adornee = nil
end)
end
lootChamPoolWanted = nil
end
function lootPoolCleanup()
for i = 1, #lootChamPool do
pcall(function()
lootChamPool[i]:Destroy()
end)
lootChamPool[i] = nil
end
lootChamPoolWanted = nil
end
function lootPoolContains(inst)
for _, h in ipairs(lootChamPool) do
if h.Adornee == inst and h.Enabled then
return true
end
end
return false
end
function lootPoolUpdate(myRoot, now)
local bagOn = S.Loot.Enabled and S.Loot.Chams
local contOn = S.LootC.Enabled and S.LootC.Chams
local wanted = (bagOn or contOn) and not lootChamPoolBlocked
if not wanted then
if lootChamPoolWanted ~= false then
lootPoolDisableAll()
lootChamPoolWanted = false
end
return
end
if now - lootChamPoolAt < LOOT_POOL_INTERVAL then
return
end
lootChamPoolAt = now
local list = {}
for inst, e in pairs(trackedBackpacks) do
if inst.Parent and inst:IsDescendantOf(Workspace) then
local cat = e.Cat or "bag"
local catOn = (cat == "bag" and bagOn) or (cat == "cont" and contOn)
if catOn then
local okD, d = pcall(function()
return (inst:GetPivot().Position - myRoot.Position).Magnitude
end)
if okD and d then
local maxD = (cat == "bag") and S.Loot.MaxDistance or S.LootC.MaxDistance
if d <= maxD * 1.06 + 10 then
table.insert(list, { inst = inst, d = d, cat = cat })
end
end
end
end
end
if #list > 1 then
table.sort(list, function(a, b)
return a.d < b.d
end)
end
local used = 0
for i = 1, math.min(#list, LOOT_POOL_SIZE) do
local item = list[i]
local h = lootChamPool[used + 1]
if not h then
local okH, created = pcall(function()
local nh = Instance.new("Highlight")
nh.Name = "PETUH_LootChamPool"
nh.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
nh.FillTransparency = 0.45
nh.OutlineTransparency = 0
nh.Parent = Workspace
return nh
end)
if okH and created then
h = created
lootChamPool[used + 1] = created
else
lootChamPoolBlocked = true
warn("[FUST] Пул чамсов лута недоступен — откат на квадраты-заливки")
break
end
end
used = used + 1
pcall(function()
h.Adornee = item.inst
h.FillColor = (item.cat == "bag") and LOOT_COLOR or LOOTC_COLOR
h.OutlineColor = (item.cat == "bag") and LOOT_COLOR or LOOTC_COLOR
h.Enabled = true
end)
-- 0.53 ФИКС «ЧАМСЫ ЛУТА НЕ РАБОТАЮТ»: если игра сносит Highlight из
-- Workspace (pcall не падает, но Parent становится nil), раньше чамсы
-- молча не рисовались. Теперь детектим и включаем квадраты-заливки.
if not h.Parent then
lootChamPoolBlocked = true
LootChamsBlocked = true
LootChamsBlockedAt = os.clock()
break
end
end
for i = used + 1, #lootChamPool do
pcall(function()
lootChamPool[i].Enabled = false
lootChamPool[i].Adornee = nil
end)
end
lootChamPoolWanted = true
end
function updateBackpackEsp(camera, myRoot)
for inst in pairs(trackedBackpacks) do
if not inst.Parent or not inst:IsDescendantOf(Workspace) then
bpRemoveDrawings(inst)
bpOpenCacheInst[inst] = nil
trackedBackpacks[inst] = nil
end
end
if (not S.Loot.Enabled and not S.LootC.Enabled) or not myRoot then
bpHideAll()
return
end
local now = os.clock()
for inst, e in pairs(trackedBackpacks) do
local cat = e.Cat or "bag"
local catOn = (cat == "bag" and S.Loot.Enabled) or (cat == "cont" and S.LootC.Enabled)
if not catOn then
bpHideDrawings(inst)
else
local cf, sz = bpGetBBox(inst)
local dist = cf and (cf.Position - myRoot.Position).Magnitude
local maxD = (cat == "bag") and S.Loot.MaxDistance or S.LootC.MaxDistance
local col = (cat == "bag") and LOOT_COLOR or LOOTC_COLOR
if cf and dist and dist <= maxD * 1.06 + 10 then
local topLeft, boxSize = bpProject(camera, cf, sz)
if topLeft then
local MINW, MINH = 8, 11
if boxSize.X < MINW or boxSize.Y < MINH then
local cx, cy = topLeft.X + boxSize.X * 0.5, topLeft.Y + boxSize.Y * 0.5
local w = math.max(boxSize.X, MINW)
local h = math.max(boxSize.Y, MINH)
topLeft = Vector2.new(cx - w * 0.5, cy - h * 0.5)
boxSize = Vector2.new(w, h)
end
local pad = 2
local bx = topLeft.X - pad
local by = topLeft.Y - pad
local bw = boxSize.X + pad * 2
local bh = boxSize.Y + pad * 2
local centerX = bx + bw * 0.5
local ed = bpEnsureDrawings(inst)
-- 0.53 ФИКС ЛАГА: слоты/владелец читаются ТОЛЬКО у мешков в радиусе
-- отрисовки. Раньше bpReadInfo гонялся по КАЖДОМУ отслеженному мешку
-- (атрибуты + дети + промпт + тексты) — на сотнях мешков лагало даже на ПК.
if cat == "bag" and (not e.InfoAt or now - e.InfoAt > 6) then
local deep = not e.DeepAt or now - e.DeepAt > 60
if deep then
e.DeepAt = now
end
e.Info = bpReadInfo(inst, deep)
e.InfoAt = now
end
local info = e.Info or {}
local wantChams = (cat == "bag" and S.Loot.Enabled and S.Loot.Chams)
or (cat == "cont" and S.LootC.Enabled and S.LootC.Chams)
if e.High then
pcall(function()
e.High:Destroy()
end)
e.High = nil
end
if wantChams then
if LootChamsBlocked and os.clock() - (LootChamsBlockedAt or 0) > 30 then
LootChamsBlocked = false
end
if LootChamsBlocked then
ed.Fill.Color = col
ed.Fill.Transparency = 0.55
ed.Fill.Position = Vector2.new(bx, by)
ed.Fill.Size = Vector2.new(bw, bh)
ed.Fill.Visible = true
else
ed.Fill.Visible = false
end
else
ed.Fill.Visible = false
end
if (cat == "bag" and S.Loot.Box) or (cat == "cont" and S.LootC.Box) then
ed.Box.Position = Vector2.new(bx, by)
ed.Box.Size = Vector2.new(bw, bh)
ed.Box.Color = col
ed.Box.Visible = true
else
ed.Box.Visible = false
end
local textY = by + bh + 3
if cat == "bag" and S.Loot.Slots then
ed.Slots.Text = info.Slots or "открой мешок 1 раз"
ed.Slots.Position = Vector2.new(centerX, textY)
ed.Slots.Color = col
ed.Slots.Visible = true
textY = textY + 17
elseif cat == "cont" and S.LootC.Name then
local nm = "контейнер"
pcall(function()
nm = tostring(inst.Name)
if #nm > 22 then
nm = string.sub(nm, 1, 22) .. "…"
end
end)
ed.Slots.Text = nm
ed.Slots.Position = Vector2.new(centerX, textY)
ed.Slots.Color = col
ed.Slots.Visible = true
textY = textY + 17
else
ed.Slots.Visible = false
end
if (cat == "bag" and S.Loot.Distance) or (cat == "cont" and S.LootC.Distance) then
ed.Distance.Text = math.floor(dist + 0.5) .. "m"
ed.Distance.Position = Vector2.new(centerX, textY)
ed.Distance.Color = col
ed.Distance.Visible = true
else
ed.Distance.Visible = false
end
if cat == "bag" and S.Loot.Owner and info.Owner then
ed.Owner.Text = tostring(info.Owner)
ed.Owner.Position = Vector2.new(centerX, by - 18)
ed.Owner.Color = col
ed.Owner.Visible = true
else
ed.Owner.Visible = false
end
else
bpHideDrawings(inst)
end
else
bpHideDrawings(inst)
if dist and dist > maxD * 1.25 + 50 then
bpRemoveDrawings(inst)
end
end
end
end
end
task.spawn(function()
