end
task.wait(10)
end
end)
velEMA = {} 
velEMALastClean = 0
function autoLead(dist)
return math.clamp(dist / 900, 0.1, 1.5) * math.clamp(Aim.AutoPredictK or 1, 0.1, 5)
end
function getSmoothedVelocity(root, vel)
if not Aim.AutoPredict then
return vel
end
local old = velEMA[root]
if not old then
velEMA[root] = vel
return vel
end
local smooth = old:Lerp(vel, 0.35)
velEMA[root] = smooth
return smooth
end
-- 0.50: КОПТЕРЫ — отдельная цель аимбота. По приказу: БЕЗ проверки
-- дистанции (лимит Aim.Distance срезал летающие далеко/высоко коптеры,
-- из-за этого «аим не работал на коптеры»). FOV и проверка стен (если
-- включены) остаются как у остальных целей.
trackedCopters = {}
local copterChecked = {}
local lastCopterScan = 0
function resolveCopterPart(model)
local seat = model:FindFirstChildWhichIsA("VehicleSeat", true)
if seat then return seat end
local pp = model.PrimaryPart
if pp and pp.Parent then return pp end
local best = nil
for _, d in ipairs(model:GetDescendants()) do
if d:IsA("BasePart") and (not best or d.Size.Magnitude > best.Size.Magnitude) then
best = d
end
end
return best
end
function refreshCopters()
local myChar = LocalPlayer.Character
for model in pairs(trackedCopters) do
if not model.Parent then
trackedCopters[model] = nil
end
end
for model in pairs(copterChecked) do
if not model.Parent then
copterChecked[model] = nil
end
end
local function tryCopter(obj)
if not obj:IsA("Model") or trackedCopters[obj] or copterChecked[obj] then
return
end
if isPlayerCharacter(obj) then
return
end
if myChar and obj:IsAncestorOf(myChar) then
return
end
local name = string.lower(obj.Name)
local byName = string.find(name, "copter", 1, true)
or string.find(name, "heli", 1, true)
or string.find(name, "вертол", 1, true)
local isCopter = false
if byName then
isCopter = true
else
local seat = obj:FindFirstChildWhichIsA("VehicleSeat", true)
if seat then
isCopter = true
end
end
if isCopter then
local part = resolveCopterPart(obj)
if part then
trackedCopters[obj] = part
end
else
copterChecked[obj] = true
end
end
for _, obj in ipairs(Workspace:GetChildren()) do
if obj:IsA("Model") then
tryCopter(obj)
elseif obj:IsA("Folder") then
for _, obj2 in ipairs(obj:GetChildren()) do
if obj2:IsA("Model") then
tryCopter(obj2)
end
end
end
end
end
task.spawn(function()
while getgenv().FUST_SESSION == FUST_SESSION do
if Aim.TargetsCopters and os.clock() - lastCopterScan > 2 then
lastCopterScan = os.clock()
pcall(refreshCopters)
end
task.wait(1)
end
end)

function getAimTarget(camera)
local char = LocalPlayer.Character
local localRoot = char and char:FindFirstChild("HumanoidRootPart")
if not localRoot then
return nil
end
local camPos = camera.CFrame.Position
local look = camera.CFrame.LookVector
local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
local bestPart, bestPoint, bestType
local bestScore = math.huge
local now = os.clock()
if now - velEMALastClean > 30 then
velEMALastClean = now
for root in pairs(velEMA) do
if not root.Parent then
velEMA[root] = nil
end
end
end
if Aim.TargetsPlayers ~= false then
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= LocalPlayer
and Whitelist[plr.Name] == nil
and not (Aim.TeamCheck and plr.Team ~= nil and plr.Team == LocalPlayer.Team) then
local model = plr.Character
local hum = model and model:FindFirstChildOfClass("Humanoid")
local root = model and model:FindFirstChild("HumanoidRootPart")
if hum and root and hum.Health > 0 then
local worldDist = (root.Position - localRoot.Position).Magnitude
if worldDist <= Aim.Distance then
if Evil.Enabled then
local evPart, evPos = evilAimPoint(model, root, camPos, worldDist)
if evPart and evPos then
local toEv = evPos - camPos
if toEv:Dot(look) > 0 then
local sp = camera:WorldToViewportPoint(evPos)
local screenDist = (center - Vector2.new(sp.X, sp.Y)).Magnitude
if Evil.Snipe or screenDist <= Aim.FOV then
local score = (not Evil.Snipe and Aim.Priority == "Дистанция") and worldDist or screenDist
if score < bestScore then
bestScore = score
bestPart = evPart
bestPoint = evPos
bestType = "игрок (злой)"
end
end
end
end
else
local part = resolveAimPart(model, Aim.Part)
if part then
local vel = root.AssemblyLinearVelocity
local lead = Aim.AutoPredict and autoLead(worldDist) or Aim.Prediction
local aimPos = part.Position + vel * lead
local toPoint = aimPos - camPos
if toPoint:Dot(look) > 0 then
local sp = camera:WorldToViewportPoint(aimPos)
local screenDist = (center - Vector2.new(sp.X, sp.Y)).Magnitude
if screenDist <= Aim.FOV then
if not Aim.WallCheck or not wallBetween(camPos, model, aimPos) then
local score = (Aim.Priority == "Дистанция") and worldDist or screenDist
if score < bestScore then
bestScore = score
bestPart = part
bestPoint = aimPos
bestType = "игрок"
end
end
end
end
end
end
end
end
end
end
end
if Aim.TargetsNPC or Aim.TargetsAnimals or Aim.TargetsSleepers then
for model in pairs(trackedNPCs) do
local hum = model and model:FindFirstChildOfClass("Humanoid")
local root = model and model:FindFirstChild("HumanoidRootPart")
if hum and root and hum.Health > 0 then
local aimCat = npcGetCategory(model, hum, root)
local catWanted =
((aimCat == "Guard" or aimCat == "Peaceful") and Aim.TargetsNPC)
or (aimCat == "Animal" and Aim.TargetsAnimals)
or (aimCat == "Sleeper" and Aim.TargetsSleepers)
if not catWanted then
continue
end
local worldDist = (root.Position - localRoot.Position).Magnitude
if worldDist <= Aim.Distance then
local part = resolveAimPart(model, Aim.Part)
if part then
local vel = getSmoothedVelocity(root, root.AssemblyLinearVelocity)
local lead = Aim.AutoPredict and autoLead(worldDist) or Aim.Prediction
local aimPos = part.Position + vel * lead
local toPoint = aimPos - camPos
if toPoint:Dot(look) > 0 then
local sp = camera:WorldToViewportPoint(aimPos)
local screenDist = (center - Vector2.new(sp.X, sp.Y)).Magnitude
if screenDist <= Aim.FOV then
if not Aim.WallCheck or not wallBetween(camPos, model, aimPos) then
local score = (Aim.Priority == "Дистанция") and worldDist or screenDist
if score < bestScore then
bestScore = score
bestPart = part
bestPoint = aimPos
bestType = "бот/НПС"
end
end
end
end
end
end
end
end
end
-- 0.50: КОПТЕРЫ как цель — БЕЗ проверки дистанции (по приказу).
-- Стрелять можно и по пустому коптеру (чтобы сбить), поэтому
-- занятость сиденья не проверяем. Свой коптер (в котором сидишь) исключён.
if Aim.TargetsCopters then
for model, part in pairs(trackedCopters) do
if model.Parent and part and part.Parent then
local aimPos = part.Position
local toPoint = aimPos - camPos
if toPoint:Dot(look) > 0 then
local sp = camera:WorldToViewportPoint(aimPos)
local screenDist = (center - Vector2.new(sp.X, sp.Y)).Magnitude
if screenDist <= Aim.FOV then
if not Aim.WallCheck or not wallBetween(camPos, model, aimPos) then
-- ДИСТАНЦИЯ НЕ ПРОВЕРЯЕТСЯ: коптеры далеко/высоко —
-- лимит Aim.Distance их никогда не пропускал
local score = (Aim.Priority == "Дистанция") and (aimPos - camPos).Magnitude or screenDist
if score < bestScore then
bestScore = score
bestPart = part
bestPoint = aimPos
bestType = "коптер"
end
end
end
end
else
trackedCopters[model] = nil
end
end
end
return bestPart, bestPoint, bestType
end
if getgenv().FUST_AimCleanup then
pcall(getgenv().FUST_AimCleanup)
end
aimConnection = nil
aimConnection = RunService.RenderStepped:Connect(function(dt)
if getgenv().FUST_SESSION ~= FUST_SESSION then
aimConnection:Disconnect()
return
end
local camera = Workspace.CurrentCamera
if not camera then
return
end
local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
updateCrosshairV(dt, center)
-- 0.56: аим выключен ИЛИ фрикам — сброс цели, FOV-круг прячем
if not Aim.Enabled or FreeCam.Enabled then
AIM_TargetPart = nil
AIM_TargetScreenPos = nil
fovGuiSetVisible(false)
return
end
local part, aimPos = getAimTarget(camera)
-- 0.53: текущая цель аима — для прицела «следовать за целью/точкой аима»
AIM_TargetPart = part
if part and aimPos then
pcall(function()
local sp = camera:WorldToViewportPoint(aimPos)
AIM_TargetScreenPos = Vector2.new(sp.X, sp.Y)
end)
else
AIM_TargetScreenPos = nil
end
-- 0.56: GUI FOV-круг (вращающийся; красно-чёрный / зелёный по видимости)
fovGuiUpdate(center, part and true or false)
if part and aimPos then
AR_AimBusyUntil = os.clock() + 0.15
local newCF = CFrame.new(camera.CFrame.Position, aimPos)
if Evil.Enabled then
-- STEALTH 0.39: фикс «кривого прицеливания» злого аима.
-- Проблема 0.38: фиксированный лерп 0.85 недолёт при быстрой цели
-- (успевает убежать за 1 кадр), и перелёт при близкой (камера
-- проскакивает). Решение: лерп АДАПТИВНЫЙ по дистанции до цели.
-- < 30м → 0.92 (быстрая коррекция, цель близко — резче)
-- 30..80м → 0.85 (средне)
-- > 80м → 0.78 (далеко — меньше перелётов)
-- Snipe-режим — +0.06 ко всем (максимум 0.98).
local dist = (aimPos - camera.CFrame.Position).Magnitude
local baseA = 0.78
if dist < 30 then baseA = 0.92
elseif dist < 80 then baseA = 0.85
end
if Evil.Snipe then baseA = math.min(0.98, baseA + 0.06) end
camera.CFrame = camera.CFrame:Lerp(newCF, baseA)
else
local alpha = math.clamp(1 / math.max(Aim.Smooth, 1), 0, 1)
camera.CFrame = camera.CFrame:Lerp(newCF, alpha)
end
-- 0.39v2: АВТО-СТРЕЛЬБА
-- 0.39v4: WallCheck — не стрелять если цель за стеной
local afCanFire = AutoFire.Enabled and (not AutoFire.OnlyOnTarget or part)
if afCanFire and AutoFire.WallCheck and part and aimPos then
-- ищем модель цели для raycast (part.Parent обычно модель игрока/НПС/вертолёта)
local targetModel = part.Parent
if not targetModel or not targetModel:IsA("Model") then
targetModel = part:FindFirstAncestorOfClass("Model")
end
if targetModel then
local camPos2 = camera.CFrame.Position
if wallBetween(camPos2, targetModel, aimPos) then
afCanFire = false
end
end
end
if afCanFire then
local now = os.clock()
if now - AF_LastShot >= AutoFire.Delay then
AF_LastShot = now
AF_LastTargetPart = part
pcall(function()
-- ПК: симулируем левый клик мышью через mouse1click (если есть)
-- или VirtualInputManager. НЕ перехватываем управление телефоном.
-- 0.49 FIX: выбор ветки по РЕАЛЬНОМУ вводу — экзекуторы на телефоне врут
-- во флагах (KeyboardEnabled бывает true на Delta). Телефон = TouchEnabled.
-- 0.56 (E-20): движок ВЕРНУТ по приказу пользователя — VOMAGLA (0.52-0.55)
-- не стрелял, а этот работает на Xeno с линии 0.39.
local hasKeyboard = UserInputService.KeyboardEnabled and not UserInputService.TouchEnabled
if hasKeyboard then
-- Xeno: mouse1click / mouse1press / mouse1release
local m1c = getgenv().mouse1click
local afFired = false
if type(m1c) == "function" then
m1c()
afFired = true
else
-- фолбэк: VirtualInputManager (Roblox)
local okV, vim = pcall(function()
return game:GetService("VirtualInputManager")
end)
if okV and vim then
-- 0.39v4 FIX: task.wait здесь ЗАПРЕЩЁН (yield в RenderStepped ломает
-- весь aim loop). Шлём press+release без задержки — Roblox сам
-- обработает порядок.
vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)
vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)
afFired = true
end
end
if not afFired then
-- 0.49 FIX: mouse1click/VIM недоступны — стреляем Tool:Activate()
local afChar = LocalPlayer.Character
local afTool = afChar and afChar:FindFirstChildOfClass("Tool")
if afTool then
pcall(function()
afTool:Activate()
end)
end
end
else
-- Телефон: НЕ перехватываем управление. Авто-стрельба только если
-- в игре есть Tool с Activate() — вызываем его напрямую.
local char = LocalPlayer.Character
local tool = char and char:FindFirstChildOfClass("Tool")
if tool then
pcall(function()
tool:Activate()
end)
end
end
end)
end
end
end
end)
