if AimHotkeyObj and AimHotkeyObj.Value and AimHotkeyObj.Value ~= "None" and AimHotkeyObj.Get then
local okHK, hkKey, hkMode = pcall(function()
return AimHotkeyObj:Get()
end)
if okHK and type(hkKey) == "string" and hkKey ~= "" then
hotkeyKey = hkKey
hotkeyMode = (hkMode == "Hold" or hkMode == "Always") and hkMode or "Toggle"
end
end
