-- 0.53: ПУЛИ (ТРЕЙСЕРЫ) — ДВИЖОК VOMAGLA 1-в-1. Перехватываются РЕАЛЬНЫЕ
-- выстрелы: hookmetamethod __namecall ловит Raycast у Workspace, луч длиннее
-- 50 стадов и не дальше 5 м от камеры = чей-то выстрел вплотную к тебе
-- (практически всегда — твой). Старый детектор «быстрая часть + прямая»
-- СПАМИЛ: считал пулями любые летящие части, в т.ч. от бегущих игроков и
-- тимейтов — УДАЛЁН. Пул Beam'ов VOMAGLA: Part + 2 Attachment + Beam
-- (FaceCamera, LightEmission 1, TextureLength/Speed 2).
local btPool, btPoolSize = {}, 0
local btActive = {}
local function btGet()
if btPoolSize > 0 then
local p = btPool[btPoolSize]
btPool[btPoolSize] = nil
btPoolSize = btPoolSize - 1
return p
end
local p = Instance.new("Part")
p.Anchored = true
p.CanCollide = false
p.Transparency = 1
p.Size = Vector3.new(0.1, 0.1, 0.1)
local a0 = Instance.new("Attachment", p)
a0.Name = "A0"
local a1 = Instance.new("Attachment", p)
a1.Name = "A1"
local b = Instance.new("Beam")
b.Name = "B"
b.Attachment0 = a0
b.Attachment1 = a1
b.FaceCamera = true
b.LightEmission = 1
b.LightInfluence = 0
b.TextureLength = 2
b.TextureSpeed = 2
b.Parent = p
return p
end
local function btRelease(p, b)
if b then
b.Enabled = false
end
if p then
p.Parent = nil
btPoolSize = btPoolSize + 1
btPool[btPoolSize] = p
end
end
function btDestroyAll()
for i = #btActive, 1, -1 do
local t = btActive[i]
if t and t.p then
pcall(function() t.p:Destroy() end)
end
btActive[i] = nil
end
for i = 1, btPoolSize do
pcall(function() btPool[i]:Destroy() end)
end
btPool = {}
btPoolSize = 0
end
-- ТИМ ЧЕК ПУЛЬ: если стреляли вплотную к камере и ближе всех к точке
-- выстрела стоит тимейт — его пули не рисуем (антиспам от своих).
local function btIsTeammateShot(origin)
if not S.Bullets.TeamCheck then
return false
end
local myTeam = LocalPlayer.Team
if not myTeam then
return false
end
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= LocalPlayer and plr.Team == myTeam then
local c = plr.Character
local r = c and c:FindFirstChild("HumanoidRootPart")
if r and (r.Position - origin).Magnitude < 6 then
return true
end
end
end
return false
end
function btCreateTrace(startPos, endPos)
if not S.Bullets.Enabled then
return
end
local camera = Workspace.CurrentCamera
if camera then
local d = (startPos - camera.CFrame.Position).Magnitude
if d < 4 then
startPos = (camera.CFrame * CFrame.new(2.5, -1.5, -1)).Position
end
end
local p = btGet()
p.Parent = Workspace
local a0 = p:FindFirstChild("A0")
local a1 = p:FindFirstChild("A1")
if a0 then
a0.WorldPosition = startPos
end
if a1 then
a1.WorldPosition = endPos
end
local b = p:FindFirstChild("B")
if not b then
btRelease(p)
return
end
b.Color = ColorSequence.new(S.Bullets.Color)
b.Transparency = NumberSequence.new(S.Bullets.Transparency)
b.Texture = S.Bullets.TextureID
b.Width0 = S.Bullets.Width
b.Width1 = S.Bullets.Width
b.Enabled = true
btActive[#btActive + 1] = { p = p, b = b, start = os.clock() }
end
function FUST_TracersUpdate()
if #btActive == 0 then
return
end
local lt = math.max(S.Bullets.LifeTime or 0.5, 0.05)
local nowT = os.clock()
for i = #btActive, 1, -1 do
local t = btActive[i]
local p, b = t.p, t.b
if not p or not p.Parent then
table.remove(btActive, i)
else
local alpha = 1 - ((nowT - t.start) / lt)
if alpha <= 0 then
btRelease(p, b)
table.remove(btActive, i)
elseif b then
b.Transparency = NumberSequence.new(alpha * S.Bullets.Transparency)
end
end
end
end
function setBulletsEnabled(on)
if not on then
btDestroyAll()
end
end
FUST_BulletsSet = setBulletsEnabled
do
local hookOK = (type(hookmetamethod) == "function")
and (type(getnamecallmethod) == "function")
and (type(newcclosure) == "function")
if hookOK then
local okH, errH = pcall(function()
local old
old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
local method = getnamecallmethod()
if method == "Raycast" and self == Workspace and S.Bullets.Enabled then
local origin, direction, rayParams = ...
if typeof(origin) == "Vector3" and typeof(direction) == "Vector3" then
local mag = direction.Magnitude
local cam = Workspace.CurrentCamera
local camPos = cam and cam.CFrame.Position
if mag > 50 and camPos and (origin - camPos).Magnitude <= 5 then
if not btIsTeammateShot(origin) then
local result = old(self, ...)
if result then
task.spawn(btCreateTrace, origin, result.Position)
end
return result
end
end
end
end
return old(self, ...)
end))
return old
end)
if okH then
print("[FUST] Пули: перехват выстрелов активен (движок VOMAGLA)")
else
warn("[FUST] Пули: hookmetamethod не сработал — трейсеров не будет: " .. tostring(errH))
end
else
warn("[FUST] Пули: в экзекуторе нет hookmetamethod — трейсеры пуль недоступны")
end
end

