function getScreenBox(camera, root)
local camCF = camera.CFrame
local camPos = camCF.Position
local look = camCF.LookVector
local cf = root.CFrame
local hx, hy, hz = BOX_SIZE.X * 0.5, BOX_SIZE.Y * 0.5, BOX_SIZE.Z * 0.5
local minX, minY = math.huge, math.huge
local maxX, maxY = -math.huge, -math.huge
for i = 0, 7 do
local ox = (i % 2 == 0) and -hx or hx
local oy = (i % 4 < 2) and -hy or hy
local oz = (i < 4) and -hz or hz
local corner = (cf * CFrame.new(ox, oy, oz)).Position
local depth = (corner - camPos):Dot(look)
if depth <= 0.1 then
return nil
end
local pt = camera:WorldToViewportPoint(corner)
if pt.X < minX then minX = pt.X end
if pt.X > maxX then maxX = pt.X end
if pt.Y < minY then minY = pt.Y end
if pt.Y > maxY then maxY = pt.Y end
end
return Vector2.new(minX, minY), Vector2.new(maxX - minX, maxY - minY)
end
function espDistScale(dist, maxDist)
if not S.ESP.DistanceScale then
return 1, false
end
local limit = math.max(maxDist or 1000, 100)
local t = math.clamp(dist / limit, 0, 1)
return 1 - t * 0.55, true
end
ESP_VIS_COLOR_WALL = Color3.fromRGB(150, 150, 150)
ESP_VIS_COLOR_HB = Color3.fromRGB(255, 190, 40)
espVisCache = {}
espVisCacheCount = 0
espVisRayParams = RaycastParams.new()
espVisRayParams.FilterType = Enum.RaycastFilterType.Exclude
espVisRayParams.IgnoreWater = true
function espVisCacheClear()
table.clear(espVisCache)
espVisCacheCount = 0
end
function espVisPointClear(camPos, char, point)
if LocalPlayer.Character then
espVisRayParams.FilterDescendantsInstances = { LocalPlayer.Character, char }
else
espVisRayParams.FilterDescendantsInstances = { char }
end
return Workspace:Raycast(camPos, point - camPos, espVisRayParams) == nil
end
function espVisState(char, root, camPos, now)
local hit = espVisCache[char]
if hit and now - hit.at < 0.2 then
return hit.state
end
if espVisCacheCount > 60 then
table.clear(espVisCache)
espVisCacheCount = 0
end
local state = "vis"
local head = char:FindFirstChild("Head") or char:FindFirstChild("UpperTorso")
local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
local bodySeen = false
if head and espVisPointClear(camPos, char, head.Position) then
bodySeen = true
end
if not bodySeen and torso and espVisPointClear(camPos, char, torso.Position) then
bodySeen = true
end
if not bodySeen then
if S.ESP.VisHitbox and root then
local hbSeen = false
local half = root.Size * 0.5
local pts = {
root.Position,
root.Position + Vector3.new(0, half.Y * 0.8, 0),
root.Position - Vector3.new(0, half.Y * 0.8, 0),
}
for _, p in ipairs(pts) do
if espVisPointClear(camPos, char, p) then
hbSeen = true
break
end
end
state = hbSeen and "hb" or "wall"
else
state = "wall"
end
end
espVisCache[char] = { state = state, at = now }
espVisCacheCount = espVisCacheCount + 1
return state
end
renderConnection = nil
renderConnection = RunService.RenderStepped:Connect(function()
if getgenv().FUST_SESSION ~= FUST_SESSION then
renderConnection:Disconnect()
return
end
